window.SCHAL={"totalRows": 324, "totalStitches": 9064, "doors": [{"nr": 1, "kniff": "Eine rechte Masche stricken", "min": "30 bis 40 Min.", "intro": "Eine rechte Masche besteht aus vier kleinen Bewegungen. Heute schaust du dir jede einzeln an. Danach strickst du die ersten Reihen deines Schals.", "blick": "Die neue Schlinge nach vorn holen", "steps": [["In die Masche einstechen", "Führe die rechte Nadel von vorn nach hinten durch das vordere Maschenglied der ersten Masche: von links unten nach rechts oben. Die alte Masche bleibt auf der linken Nadel."], ["Den Arbeitsfaden erfassen", "Lege den Arbeitsfaden gegen den Uhrzeigersinn um die rechte Nadel, wenn du direkt auf ihre Spitze schaust. Der Faden liegt hinter der Arbeit."], ["Die neue Schlinge durchholen", "Ziehe die rechte Spitze mit dem erfassten Faden durch die alte Masche nach vorn. So entsteht eine neue Schlinge auf der rechten Nadel. Teile dabei keine Garnfasern."], ["Die alte Masche lösen", "Lass erst jetzt die alte Masche von der linken Spitze gleiten. Schiebe die neue Masche auf den dicken Teil der Nadel und lege den Faden nur leicht an."]], "photos": [{"src": "assets/fotos/t01-entdecken.webp", "cap": "So sieht eine rechte Masche von vorn aus: ein V.", "slot": "entdecken"}, {"src": "assets/fotos/t01-schritt-1.webp", "cap": "1 · Die rechte Nadel sticht ein", "slot": "schritt-1"}, {"src": "assets/fotos/t01-schritt-2.webp", "cap": "2 · Der Faden liegt um die Nadel", "slot": "schritt-2"}, {"src": "assets/fotos/t01-detail-1.webp", "cap": "3 · Die neue Schlinge kommt nach vorn", "slot": "detail-1"}, {"src": "assets/fotos/t01-detail-2.webp", "cap": "4 · Die alte Masche gleitet ab", "slot": "detail-2"}, {"src": "assets/fotos/t01-ergebnis.webp", "cap": "Nur rechte Maschen: kraus rechts mit Querrippen", "slot": "ergebnis"}], "hakt": [["Die Nadel geht schwer hindurch.", "Schiebe die nächste Masche näher zur Spitze und entspanne den Faden. Stich durch die ganze Schlinge."], ["Die neue Masche ist sehr eng.", "Bilde sie auf dem dicken Teil der Nadel und ziehe nach dem Abgleiten nur sanft nach. Sie soll sich noch verschieben lassen."]], "ww": "Jeder Schal beginnt mit dem festen Vorsatz, diesmal ordentlich mitzuzählen.", "block": "Kraus-Saum", "sIntro": "Dein Schal beginnt mit einem festen Saum. Kraus rechts rollt sich nicht ein und gibt dem Schal unten eine ruhige Kante.", "sVor": "Die 28 Maschen hast du vor dem 1. Dezember angeschlagen (Seite 6). Der Anschlag zählt nicht als Reihe.", "sCheck": "28 Maschen. Auf der Vorderseite zählst du 7 Querrippen.", "sAfter": "Lass die Maschen auf der Nadel. Morgen geht es direkt weiter.", "lines": [["Reihe 1 bis 14", "28 re"]], "end": 28, "rows": [{"id": 1, "row": 1, "rs": true, "text": "28 re", "after": 28}, {"id": 2, "row": 2, "rs": false, "text": "28 re", "after": 28}, {"id": 3, "row": 3, "rs": true, "text": "28 re", "after": 28}, {"id": 4, "row": 4, "rs": false, "text": "28 re", "after": 28}, {"id": 5, "row": 5, "rs": true, "text": "28 re", "after": 28}, {"id": 6, "row": 6, "rs": false, "text": "28 re", "after": 28}, {"id": 7, "row": 7, "rs": true, "text": "28 re", "after": 28}, {"id": 8, "row": 8, "rs": false, "text": "28 re", "after": 28}, {"id": 9, "row": 9, "rs": true, "text": "28 re", "after": 28}, {"id": 10, "row": 10, "rs": false, "text": "28 re", "after": 28}, {"id": 11, "row": 11, "rs": true, "text": "28 re", "after": 28}, {"id": 12, "row": 12, "rs": false, "text": "28 re", "after": 28}, {"id": 13, "row": 13, "rs": true, "text": "28 re", "after": 28}, {"id": 14, "row": 14, "rs": false, "text": "28 re", "after": 28}], "ends": null, "bow": null, "bindoff": null, "riddle": {"title": "Buchstabensalat", "typ": "B", "hint": "Alle vier Wörter liegen heute vor dir: an der Nadel, am Knäuel und am Strickstück.", "sol": "NADEL, GARN, SPITZE, RAND.", "trap": "Bei DNAR liegt „dran“ nahe. Gesucht ist aber ein Hauptwort: der Rand."}}, {"nr": 2, "kniff": "Eine linke Masche stricken", "min": "35 bis 45 Min.", "intro": "Die linke Masche ist die Rückseite der rechten. Heute übst du vor allem, den Faden vor der Arbeit zu führen.", "blick": "Die Schlinge nach hinten holen", "steps": [["Vorn bereitmachen", "Lege den Arbeitsfaden vor die Arbeit. Führe die rechte Nadel von rechts nach links durch das vordere Maschenglied der ersten Masche. Die alte Masche bleibt auf der linken Nadel."], ["Den Faden umlegen", "Lege den Faden von oben um die rechte Nadel, gegen den Uhrzeigersinn, wenn du auf ihre Spitze schaust. Halte ihn leicht gespannt."], ["Die neue Schlinge holen", "Führe die rechte Nadelspitze mit dem erfassten Faden durch die alte Masche nach hinten. Auf der rechten Nadel entsteht die neue Schlinge."], ["Die alte Masche lösen", "Lass die alte Masche von der linken Nadel gleiten. Für die nächste linke Masche bleibt der Faden vor der Arbeit."]], "photos": [{"src": "assets/fotos/t02-entdecken.webp", "cap": "Die linke Seite: kleine Querbögen", "slot": "entdecken"}, {"src": "assets/fotos/t02-schritt-1.webp", "cap": "1 · Einstechen von rechts nach links", "slot": "schritt-1"}, {"src": "assets/fotos/t02-schritt-2.webp", "cap": "2 · Der Faden liegt um die Nadel", "slot": "schritt-2"}, {"src": "assets/fotos/t02-detail-1.webp", "cap": "3 · Die neue Schlinge kommt durch", "slot": "detail-1"}, {"src": "assets/fotos/t02-detail-2.webp", "cap": "4 · Die alte Masche gleitet ab", "slot": "detail-2"}, {"src": "assets/fotos/t02-ergebnis.webp", "cap": "Glatt rechts: vorn nur V-Maschen", "slot": "ergebnis"}], "hakt": [["Die Masche sitzt fest.", "Schiebe sie näher zur linken Spitze. Halte den Faden lockerer und lass der neuen Schlinge etwas Raum."], ["Der Faden ist hinten.", "Lege ihn zwischen den Nadelspitzen nach vorn, bevor du einstichst. Führe ihn dabei nicht über die Nadel."]], "ww": "Eine linke Masche ist eine rechte Masche von hinten. Wie bei manchen Menschen.", "block": "Glatt mit Blende", "sIntro": "Jetzt wird es glatt: vorn V-Maschen, hinten Querbögen. Damit sich der Rand nicht einrollt, bleiben an jeder Seite zwei Maschen immer rechts. Das ist die Blende.", "sVor": "Ab heute hat dein Schal eine Vorderseite: die Seite, die bei den Hinreihen zu dir zeigt. Häng zur Erinnerung einen kurzen Faden an diese Seite.", "sCheck": "28 Maschen. Vorn liegt eine glatte Fläche zwischen zwei krausen Rändern.", "sAfter": "Siehst du, wie die zwei Randmaschen flach bleiben? Genau dafür sind sie da.", "lines": [["Alle Hinreihen", "28 re"], ["Alle Rückreihen", "2 re, 24 li, 2 re"]], "end": 28, "rows": [{"id": 15, "row": 1, "rs": true, "text": "28 re", "after": 28}, {"id": 16, "row": 2, "rs": false, "text": "2 re, 24 li, 2 re", "after": 28}, {"id": 17, "row": 3, "rs": true, "text": "28 re", "after": 28}, {"id": 18, "row": 4, "rs": false, "text": "2 re, 24 li, 2 re", "after": 28}, {"id": 19, "row": 5, "rs": true, "text": "28 re", "after": 28}, {"id": 20, "row": 6, "rs": false, "text": "2 re, 24 li, 2 re", "after": 28}, {"id": 21, "row": 7, "rs": true, "text": "28 re", "after": 28}, {"id": 22, "row": 8, "rs": false, "text": "2 re, 24 li, 2 re", "after": 28}, {"id": 23, "row": 9, "rs": true, "text": "28 re", "after": 28}, {"id": 24, "row": 10, "rs": false, "text": "2 re, 24 li, 2 re", "after": 28}, {"id": 25, "row": 11, "rs": true, "text": "28 re", "after": 28}, {"id": 26, "row": 12, "rs": false, "text": "2 re, 24 li, 2 re", "after": 28}, {"id": 27, "row": 13, "rs": true, "text": "28 re", "after": 28}, {"id": 28, "row": 14, "rs": false, "text": "2 re, 24 li, 2 re", "after": 28}, {"id": 29, "row": 15, "rs": true, "text": "28 re", "after": 28}, {"id": 30, "row": 16, "rs": false, "text": "2 re, 24 li, 2 re", "after": 28}], "ends": null, "bow": null, "bindoff": null, "riddle": {"title": "Nachgerechnet", "typ": "R", "hint": "Rechne erst aus, wie viele Reihen am Montag fehlen.", "sol": "24 Reihen.", "trap": "Wer nur die fehlenden 8 Reihen rechnet, vergisst Lottes normales Pensum von 16 Reihen."}}, {"nr": 3, "kniff": "Einen Kettenrand arbeiten", "min": "30 bis 40 Min.", "intro": "Ab heute bekommt dein Schal einen Rand, der wie eine kleine Kette aussieht. Die erste Masche jeder Reihe wird nur abgehoben, nicht gestrickt.", "blick": "Die erste Masche gleitet nur mit", "steps": [["Den Faden nach vorn legen", "Zu Beginn der Reihe liegt die volle Nadel links. Führe den Arbeitsfaden vor die Arbeit, ohne ihn um die Nadel zu wickeln."], ["Die erste Masche abheben", "Stich wie zum Linksstricken von rechts nach links ein und übertrage die erste Masche unverändert auf die rechte Nadel. Du holst keinen neuen Faden."], ["Den Faden nach hinten führen", "Führe den Faden zwischen den Spitzen nach hinten und stricke die zweite Masche rechts. Diese beiden Maschen sind ab heute dein Rand A."], ["Mit zwei rechten Maschen enden", "Stricke die Reihe nach Anleitung. Die letzten zwei Maschen strickst du immer rechts: dein Rand E. Dann wenden."]], "photos": [{"src": "assets/fotos/t13-entdecken.webp", "cap": "Der Kettenrand: längliche Glieder an der Seite", "slot": "entdecken"}, {"src": "assets/fotos/t13-schritt-1.webp", "cap": "Die erste Randmasche", "slot": "schritt-1"}, {"src": "assets/fotos/t13-schritt-2.webp", "cap": "Die vorhandene Schlinge erfassen", "slot": "schritt-2"}, {"src": "assets/fotos/t13-detail-1.webp", "cap": "Krausrippen zwischen den Rändern", "slot": "detail-1"}, {"src": "assets/fotos/t13-detail-2.webp", "cap": "Die nächste Randmasche auf der Nadel", "slot": "detail-2"}, {"src": "assets/fotos/t13-ergebnis.webp", "cap": "Gleichmäßige Kettenglieder an beiden Seiten", "slot": "ergebnis"}], "hakt": [["Neben dem Rand ist ein Loch.", "Prüfe, ob beim Wechsel nach hinten ein zusätzlicher Umschlag entstanden ist. Der Faden läuft zwischen den Spitzen hindurch, nicht über die Nadel."], ["Die Kante zieht sich zusammen.", "Ziehe die Masche nach dem Abheben nicht fest. Der Randfaden muss zwei Reihen überbrücken können."]], "ww": "Ein schöner Rand verzeiht vieles. Die Mitte merkt sich alles.", "block": "Kraus mit Kettenrand", "sIntro": "Noch ein Kraus-Abschnitt, diesmal mit Kettenrand. Vergleiche nachher die Seitenkante mit Türchen 1.", "sVor": "Rand A heißt ab heute: 1 Masche wie zum Linksstricken abheben, Faden vorn. Faden zwischen den Spitzen nach hinten. 1 re. Rand E heißt: 2 re.", "sCheck": "28 Maschen. An jeder Seite zählst du 7 Kettenglieder.", "sAfter": "Rand A und Rand E bleiben ab jetzt in jeder Reihe gleich. In den Anleitungen stehen sie nur noch als Rand A und Rand E.", "lines": [["Reihe 1 bis 14", "Rand A, 24 re, Rand E"]], "end": 28, "rows": [{"id": 31, "row": 1, "rs": true, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 32, "row": 2, "rs": false, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 33, "row": 3, "rs": true, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 34, "row": 4, "rs": false, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 35, "row": 5, "rs": true, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 36, "row": 6, "rs": false, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 37, "row": 7, "rs": true, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 38, "row": 8, "rs": false, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 39, "row": 9, "rs": true, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 40, "row": 10, "rs": false, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 41, "row": 11, "rs": true, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 42, "row": 12, "rs": false, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 43, "row": 13, "rs": true, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 44, "row": 14, "rs": false, "text": "Rand A, 24 re, Rand E", "after": 28}], "ends": null, "bow": null, "bindoff": null, "riddle": {"title": "Wortsuche", "typ": "W", "hint": "Fang mit dem längsten Wort an: MASCHE beginnt in Zeile 1.", "sol": "Die Lage aller acht Wörter siehst du im Lösungsgitter.", "trap": ""}}, {"nr": 4, "kniff": "Den Faden richtig wechseln", "min": "35 bis 45 Min.", "intro": "Wenn sich rechte und linke Maschen abwechseln, zieht der Faden mit um. Sein Weg entscheidet, ob ungewollt eine neue Schlinge entsteht.", "blick": "Zwischen den Spitzen hindurch", "steps": [["Mit einer rechten Masche beginnen", "Stricke die Masche rechts. Der Arbeitsfaden liegt hinter der Arbeit. Halte die Spitzen einen kleinen Abstand auseinander."], ["Den Faden nach vorn führen", "Führe den Arbeitsfaden zwischen den beiden Nadelspitzen nach vorn. Er läuft durch die Lücke und wird nicht um die rechte Nadel geschlungen."], ["Eine linke Masche stricken", "Stricke die nächste Masche links, wie in Türchen 2. Der Faden liegt dabei vor der Arbeit. Ziehe die fertige Masche nicht fest."], ["Den Faden zurückführen", "Führe den Faden zwischen den Nadelspitzen wieder nach hinten. Jetzt ist die nächste rechte Masche dran."]], "photos": [{"src": "assets/fotos/t03-entdecken.webp", "cap": "Rippen: rechte und linke Maschen im Wechsel", "slot": "entdecken"}, {"src": "assets/fotos/t03-schritt-1.webp", "cap": "Die Nadeln leicht auseinanderhalten", "slot": "schritt-1"}, {"src": "assets/fotos/t03-schritt-2.webp", "cap": "Der Weg zwischen den Spitzen", "slot": "schritt-2"}, {"src": "assets/fotos/t03-detail-1.webp", "cap": "Die Fadenlage beim Wechsel prüfen", "slot": "detail-1"}, {"src": "assets/fotos/t03-detail-2.webp", "cap": "Ohne zusätzlichen Umschlag weiterarbeiten", "slot": "detail-2"}, {"src": "assets/fotos/t03-ergebnis.webp", "cap": "Schmale Rippen aus rechten und linken Maschen", "slot": "ergebnis"}], "hakt": [["Eine zusätzliche Schlinge erscheint.", "Wahrscheinlich ist der Faden über die Nadel statt zwischen den Spitzen gewandert. Prüfe den letzten Wechsel, bevor du weiterstrickst."], ["Der Übergang wird locker.", "Führe den Faden dicht an den Spitzen entlang. Nach der nächsten Masche legst du ihn sanft an."]], "ww": "Zwischen den Nadelspitzen hindurch. Nicht drüber, nicht drunter. Klingt leicht, um zehn Uhr abends.", "block": "Rippen 1:1", "sIntro": "Schmale Rippen. Sie ziehen den Schal an dieser Stelle etwas zusammen und machen ihn elastisch. Das ist gewollt.", "sVor": "Nach Rand A liegt der Faden hinten. Nach der letzten linken Mustermasche muss er für Rand E wieder nach hinten.", "sCheck": "28 Maschen. In jeder Reihe 12 rechte und 12 linke Mustermaschen.", "sAfter": "Jede Reihe ist gleich. Du brauchst heute keine Hin- und Rückreihen zu unterscheiden.", "lines": [["Reihe 1 bis 16", "Rand A, 12-mal [1 re, 1 li], Rand E"]], "end": 28, "rows": [{"id": 45, "row": 1, "rs": true, "text": "Rand A, 12-mal [1 re, 1 li], Rand E", "after": 28}, {"id": 46, "row": 2, "rs": false, "text": "Rand A, 12-mal [1 re, 1 li], Rand E", "after": 28}, {"id": 47, "row": 3, "rs": true, "text": "Rand A, 12-mal [1 re, 1 li], Rand E", "after": 28}, {"id": 48, "row": 4, "rs": false, "text": "Rand A, 12-mal [1 re, 1 li], Rand E", "after": 28}, {"id": 49, "row": 5, "rs": true, "text": "Rand A, 12-mal [1 re, 1 li], Rand E", "after": 28}, {"id": 50, "row": 6, "rs": false, "text": "Rand A, 12-mal [1 re, 1 li], Rand E", "after": 28}, {"id": 51, "row": 7, "rs": true, "text": "Rand A, 12-mal [1 re, 1 li], Rand E", "after": 28}, {"id": 52, "row": 8, "rs": false, "text": "Rand A, 12-mal [1 re, 1 li], Rand E", "after": 28}, {"id": 53, "row": 9, "rs": true, "text": "Rand A, 12-mal [1 re, 1 li], Rand E", "after": 28}, {"id": 54, "row": 10, "rs": false, "text": "Rand A, 12-mal [1 re, 1 li], Rand E", "after": 28}, {"id": 55, "row": 11, "rs": true, "text": "Rand A, 12-mal [1 re, 1 li], Rand E", "after": 28}, {"id": 56, "row": 12, "rs": false, "text": "Rand A, 12-mal [1 re, 1 li], Rand E", "after": 28}, {"id": 57, "row": 13, "rs": true, "text": "Rand A, 12-mal [1 re, 1 li], Rand E", "after": 28}, {"id": 58, "row": 14, "rs": false, "text": "Rand A, 12-mal [1 re, 1 li], Rand E", "after": 28}, {"id": 59, "row": 15, "rs": true, "text": "Rand A, 12-mal [1 re, 1 li], Rand E", "after": 28}, {"id": 60, "row": 16, "rs": false, "text": "Rand A, 12-mal [1 re, 1 li], Rand E", "after": 28}], "ends": null, "bow": null, "bindoff": null, "riddle": {"title": "Wer strickt was?", "typ": "L", "hint": "Beginne mit dem Hinweis, der eine Person oder eine Farbe direkt festlegt, und streiche in einer Tabelle.", "sol": "Renate strickt einen grünen Schal, Yusuf graue Socken, Wiebke eine rote Mütze.", "trap": "Den Anfang machen die grauen Socken: Renate strickt grün, Wiebke keine Socken, also bleibt nur Yusuf."}}, {"nr": 5, "kniff": "Maschen im Gestrick lesen", "min": "35 bis 45 Min.", "intro": "Ein Blick auf die Masche zeigt dir, was als Nächstes kommt. Heute strickst du ein Muster, ohne mitzuzählen: einfach so, wie die Maschen erscheinen.", "blick": "Die andere Seite erkennen", "steps": [["Die Vorderseite ansehen", "Lege dein Stück mit der glatten Seite zu dir. Die Maschen bilden senkrechte Spalten. In jeder Spalte liegt ein kleines V über dem nächsten."], ["Ein ganzes V verfolgen", "Zeige mit einer stumpfen Nadel auf eine Masche. Ihre beiden schrägen Schenkel gehören zu einem einzigen V. Das V ist das Bild einer rechten Masche."], ["Das Stück umdrehen", "Auf der Rückseite liegen kleine Querbögen. Das ist die Rückseite derselben Maschen und das Bild einer linken Masche."], ["Direkt unter die Nadel schauen", "Schau bei der nächsten Masche auf den Bereich direkt unter der Nadel. Ein V heißt: rechts stricken. Ein Querbogen heißt: links stricken."]], "photos": [{"src": "assets/fotos/t04-entdecken.webp", "cap": "Beide Seiten auf einen Blick: V und Querbogen", "slot": "entdecken"}, {"src": "assets/fotos/t04-schritt-1.webp", "cap": "V-Spalten auf der Vorderseite", "slot": "schritt-1"}, {"src": "assets/fotos/t04-schritt-2.webp", "cap": "Die beiden Schenkel einer Masche", "slot": "schritt-2"}, {"src": "assets/fotos/t04-detail-1.webp", "cap": "Querbögen erkennen", "slot": "detail-1"}, {"src": "assets/fotos/t04-detail-2.webp", "cap": "Die linke Maschenerscheinung im Detail", "slot": "detail-2"}, {"src": "assets/fotos/t04-ergebnis.webp", "cap": "Vorn V-Maschen, hinten Querbögen", "slot": "ergebnis"}], "hakt": [["Alles sieht gleich aus.", "Halte die Fläche locker auseinander und sorge für Licht von der Seite."], ["Die Nadel verdeckt die Form.", "Ziehe das Gestrick unterhalb der Nadel leicht nach unten und schau auf die erste vollständige Masche darunter."]], "ww": "Wer Maschen lesen kann, braucht keine Brille. Nur gutes Licht. Und eine Brille.", "block": "Rippen 2:2", "sIntro": "Breitere Rippen. Ab der zweiten Reihe musst du nicht mehr mitzählen: Stricke jede Masche so, wie sie dir erscheint.", "sVor": "", "sCheck": "28 Maschen. In jeder Reihe 6 Paare rechte und 6 Paare linke Mustermaschen.", "sAfter": "„Maschen stricken, wie sie erscheinen“ steht in vielen Anleitungen. Ab heute weißt du, was gemeint ist.", "lines": [["Reihe 1 bis 16", "Rand A, 6-mal [2 re, 2 li], Rand E"]], "end": 28, "rows": [{"id": 61, "row": 1, "rs": true, "text": "Rand A, 6-mal [2 re, 2 li], Rand E", "after": 28}, {"id": 62, "row": 2, "rs": false, "text": "Rand A, 6-mal [2 re, 2 li], Rand E", "after": 28}, {"id": 63, "row": 3, "rs": true, "text": "Rand A, 6-mal [2 re, 2 li], Rand E", "after": 28}, {"id": 64, "row": 4, "rs": false, "text": "Rand A, 6-mal [2 re, 2 li], Rand E", "after": 28}, {"id": 65, "row": 5, "rs": true, "text": "Rand A, 6-mal [2 re, 2 li], Rand E", "after": 28}, {"id": 66, "row": 6, "rs": false, "text": "Rand A, 6-mal [2 re, 2 li], Rand E", "after": 28}, {"id": 67, "row": 7, "rs": true, "text": "Rand A, 6-mal [2 re, 2 li], Rand E", "after": 28}, {"id": 68, "row": 8, "rs": false, "text": "Rand A, 6-mal [2 re, 2 li], Rand E", "after": 28}, {"id": 69, "row": 9, "rs": true, "text": "Rand A, 6-mal [2 re, 2 li], Rand E", "after": 28}, {"id": 70, "row": 10, "rs": false, "text": "Rand A, 6-mal [2 re, 2 li], Rand E", "after": 28}, {"id": 71, "row": 11, "rs": true, "text": "Rand A, 6-mal [2 re, 2 li], Rand E", "after": 28}, {"id": 72, "row": 12, "rs": false, "text": "Rand A, 6-mal [2 re, 2 li], Rand E", "after": 28}, {"id": 73, "row": 13, "rs": true, "text": "Rand A, 6-mal [2 re, 2 li], Rand E", "after": 28}, {"id": 74, "row": 14, "rs": false, "text": "Rand A, 6-mal [2 re, 2 li], Rand E", "after": 28}, {"id": 75, "row": 15, "rs": true, "text": "Rand A, 6-mal [2 re, 2 li], Rand E", "after": 28}, {"id": 76, "row": 16, "rs": false, "text": "Rand A, 6-mal [2 re, 2 li], Rand E", "after": 28}], "ends": null, "bow": null, "bindoff": null, "riddle": {"title": "Finde den Fehler", "typ": "F", "hint": "Zähle bei jeder Reihe alle Maschen zusammen, die Ränder mit je 2.", "sol": "C.", "trap": "C hat nur 22 Mustermaschen und verbraucht insgesamt 26 Maschen. Zwei blieben auf der linken Nadel liegen."}}, {"nr": 6, "kniff": "Maschen sicher zählen", "min": "30 bis 40 Min.", "intro": "Eine kurze Zählpause erspart langes Suchen. Heute zählst du die Maschen direkt auf der Nadel.", "blick": "Eine Schlinge ist eine Masche", "steps": [["Auf den Schaft schieben", "Schiebe die Maschen vom spitzen Ende auf den gleichmäßig dicken Teil der Nadel. Dort rutschen sie beim Zählen nicht ab."], ["Etwas Abstand schaffen", "Verteile die Schlingen locker auf dem Nadelschaft. Jede Schlinge soll einzeln erkennbar sein."], ["Schlinge für Schlinge zählen", "Berühre jede vollständige Schlinge einmal mit einer Zeigerspitze. Eine Schlinge zählt als eine Masche, ihre zwei Fadenschenkel nicht getrennt."], ["In Gruppen prüfen", "Zähle ein zweites Mal in Vierergruppen. Sieben Gruppen ergeben 28. Die Ringe zählen später nie mit."]], "photos": [{"src": "assets/fotos/t05-entdecken.webp", "cap": "Zählen direkt auf der Nadel", "slot": "entdecken"}, {"src": "assets/fotos/t05-schritt-1.webp", "cap": "Auf dem gleichmäßig dicken Schaft zählen", "slot": "schritt-1"}, {"src": "assets/fotos/t05-schritt-2.webp", "cap": "Die Schlingen leicht auseinanderziehen", "slot": "schritt-2"}, {"src": "assets/fotos/t05-detail-1.webp", "cap": "Eine ganze Schlinge zählt einmal", "slot": "detail-1"}, {"src": "assets/fotos/t05-detail-2.webp", "cap": "Zur Kontrolle erneut zählen", "slot": "detail-2"}, {"src": "assets/fotos/t05-ergebnis.webp", "cap": "Jede Schlinge auf der Nadel ist eine Masche", "slot": "ergebnis"}], "hakt": [["Du kommst auf die doppelte Zahl.", "Du hast vermutlich beide Seiten jeder Schlinge einzeln gezählt. Eine Schlinge umschließt die Nadel nur einmal."], ["Du zählst 27 oder 29.", "Stricke nicht weiter. Suche eine heruntergerutschte Masche oder eine zusätzliche lose Schlinge."]], "ww": "Achtundzwanzig. Achtundzwanzig. Siebenundzwanzig? Noch mal von vorn.", "block": "Kraus-Streifen", "sIntro": "Ein ruhiger Kraus-Abschnitt. Ideal für die Zählpause: Nach jeder zweiten Reihe einmal durchzählen.", "sVor": "", "sCheck": "28 Maschen, in Vierergruppen gezählt: 7 Gruppen.", "sAfter": "Gewöhn dir die kurze Kontrolle an. Eine Reihe zu prüfen geht schneller, als viele Reihen später eine Masche zu suchen.", "lines": [["Reihe 1 bis 14", "Rand A, 24 re, Rand E"]], "end": 28, "rows": [{"id": 77, "row": 1, "rs": true, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 78, "row": 2, "rs": false, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 79, "row": 3, "rs": true, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 80, "row": 4, "rs": false, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 81, "row": 5, "rs": true, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 82, "row": 6, "rs": false, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 83, "row": 7, "rs": true, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 84, "row": 8, "rs": false, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 85, "row": 9, "rs": true, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 86, "row": 10, "rs": false, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 87, "row": 11, "rs": true, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 88, "row": 12, "rs": false, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 89, "row": 13, "rs": true, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 90, "row": 14, "rs": false, "text": "Rand A, 24 re, Rand E", "after": 28}], "ends": null, "bow": null, "bindoff": null, "riddle": {"title": "Nachgezählt", "typ": "R", "hint": "7 Gruppen zu je 4 sind 28. Was bedeutet die einzelne Masche?", "sol": "29 Maschen, also eine zu viel. Irgendwo ist ungewollt eine Masche dazugekommen, am häufigsten durch einen Umschlag, weil der Faden über die Nadel statt zwischen den Spitzen gewandert ist.", "trap": "7 Gruppen allein ergeben schon 28. Die einzelne Masche ist die überzählige."}}, {"nr": 7, "kniff": "Gestrickte Reihen zählen", "min": "35 bis 45 Min.", "intro": "Maschen zählst du quer, Reihen zählst du nach oben. In einer glatten Fläche lässt sich das am besten üben.", "blick": "In derselben Spalte bleiben", "steps": [["Die glatte Seite nach oben legen", "Lege den Schal mit der Vorderseite zu dir. Lass die Maschen auf der Nadel. Streiche die Fläche locker glatt, ohne zu ziehen."], ["Eine mittlere Spalte wählen", "Suche eine V-Spalte in der Mitte. Am Rand sind Maschen oft verzogen und schwerer zu zählen."], ["V für V nach oben gehen", "Zähle jedes V dieser einen Spalte einmal, vom ersten V über dem Kraus-Abschnitt nach oben. Springe nicht in die Nachbarspalte."], ["Die Reihe auf der Nadel mitzählen", "Die Masche auf der Nadel gehört zur zuletzt gestrickten Reihe. Zähle sie mit und vergleiche mit deinen Strichen."]], "photos": [{"src": "assets/fotos/t06-entdecken.webp", "cap": "Reihen zählst du nach oben", "slot": "entdecken"}, {"src": "assets/fotos/t06-schritt-1.webp", "cap": "Das Gestrick ohne Zug flachlegen", "slot": "schritt-1"}, {"src": "assets/fotos/t06-schritt-2.webp", "cap": "In der Mitte eine Spalte wählen", "slot": "schritt-2"}, {"src": "assets/fotos/t06-detail-1.webp", "cap": "Den V-Maschen nach oben folgen", "slot": "detail-1"}, {"src": "assets/fotos/t06-detail-2.webp", "cap": "Die Masche auf der Nadel mitzählen", "slot": "detail-2"}, {"src": "assets/fotos/t06-ergebnis.webp", "cap": "Eine Spalte, Reihe für Reihe", "slot": "ergebnis"}], "hakt": [["Du verlierst die Spalte.", "Lege eine stumpfe Nadel längs neben die Spalte. So behältst du die Richtung."], ["Am Rand zählst du weniger.", "Randmaschen sehen anders aus. Zähle im Inneren der Fläche."]], "ww": "Andere zählen Schafe zum Einschlafen. Strickerinnen zählen Reihen und bleiben hellwach.", "block": "Glatte Fläche", "sIntro": "Eine glatte Fläche zum Reihenzählen. Mach nach jeder Reihe einen Strich auf einen Zettel und vergleiche am Ende.", "sVor": "", "sCheck": "28 Maschen. In einer mittleren Spalte zählst du 16 V.", "sAfter": "Die Strichliste ist eine Lernhilfe. Bald liest du die Reihen direkt im Gestrick ab.", "lines": [["Alle Hinreihen", "Rand A, 24 re, Rand E"], ["Alle Rückreihen", "Rand A, 24 li, Rand E"]], "end": 28, "rows": [{"id": 91, "row": 1, "rs": true, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 92, "row": 2, "rs": false, "text": "Rand A, 24 li, Rand E", "after": 28}, {"id": 93, "row": 3, "rs": true, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 94, "row": 4, "rs": false, "text": "Rand A, 24 li, Rand E", "after": 28}, {"id": 95, "row": 5, "rs": true, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 96, "row": 6, "rs": false, "text": "Rand A, 24 li, Rand E", "after": 28}, {"id": 97, "row": 7, "rs": true, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 98, "row": 8, "rs": false, "text": "Rand A, 24 li, Rand E", "after": 28}, {"id": 99, "row": 9, "rs": true, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 100, "row": 10, "rs": false, "text": "Rand A, 24 li, Rand E", "after": 28}, {"id": 101, "row": 11, "rs": true, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 102, "row": 12, "rs": false, "text": "Rand A, 24 li, Rand E", "after": 28}, {"id": 103, "row": 13, "rs": true, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 104, "row": 14, "rs": false, "text": "Rand A, 24 li, Rand E", "after": 28}, {"id": 105, "row": 15, "rs": true, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 106, "row": 16, "rs": false, "text": "Rand A, 24 li, Rand E", "after": 28}], "ends": null, "bow": null, "bindoff": null, "riddle": {"title": "Buchstabensalat", "typ": "B", "hint": "Ein Wort hat einen Umlaut. Ein anderes misst.", "sol": "REIHE, WOLLE, KNÄUEL, LINEAL.", "trap": "NIELAL lässt sich auch zu „allein“ legen. Das ist aber kein Hauptwort."}}, {"nr": 8, "kniff": "Einen Maschenmarkierer setzen", "min": "35 bis 45 Min.", "intro": "Ein kleiner Ring merkt sich eine Stelle für dich. Ab heute trennen zwei Ringe den Rand vom Muster.", "blick": "Die Markierung mitnehmen", "steps": [["Die Stelle erreichen", "Stricke Rand A. Halte einen geschlossenen Ring bereit. Er kommt auf die Nadel, nicht durch eine Masche."], ["Den Ring aufsetzen", "Schiebe den Ring über die Spitze der rechten Nadel. Er liegt jetzt direkt neben den beiden Randmaschen."], ["Den zweiten Ring setzen", "Stricke die 24 Mustermaschen. Vor den letzten zwei Maschen setzt du den zweiten Ring auf. Dann folgt Rand E."], ["In der nächsten Reihe weiterreichen", "Erreichst du einen Ring, schiebst du ihn einfach von der linken auf die rechte Nadel. Er zählt nie als Masche."]], "photos": [{"src": "assets/fotos/t10-entdecken.webp", "cap": "Ein Ring markiert eine Stelle", "slot": "entdecken"}, {"src": "assets/fotos/t10-schritt-1.webp", "cap": "Den Ring bereitlegen", "slot": "schritt-1"}, {"src": "assets/fotos/t10-schritt-2.webp", "cap": "Den Ring an die Nadelspitze führen", "slot": "schritt-2"}, {"src": "assets/fotos/t10-detail-1.webp", "cap": "Die Markierung zwischen den Maschen", "slot": "detail-1"}, {"src": "assets/fotos/t10-detail-2.webp", "cap": "Den Ring auf die rechte Nadel nehmen", "slot": "detail-2"}, {"src": "assets/fotos/t10-ergebnis.webp", "cap": "Der Ring bleibt zwischen denselben Maschen", "slot": "ergebnis"}], "hakt": [["Du willst den Ring abstricken.", "Halte vor ihm kurz an und setze ihn um. Er gehört nicht zum Garn."], ["Der Ring sitzt im Gestrick fest.", "Ein geschlossener Ring wird nur auf die Nadel geschoben, nie durch eine Masche gesteckt."]], "ww": "Ein Maschenmarkierer kostet ein paar Cent und verschwindet trotzdem spurlos. Meistens im Sofa.", "block": "Querrippen", "sIntro": "Querrippen: Alle vier Reihen läuft eine Rippe quer über den Schal. Die Ringe zeigen dir, wo das Muster beginnt und endet.", "sVor": "In Reihe 1 setzt du die Ringe nach Rand A und vor Rand E. Danach reichst du sie nur noch weiter.", "sCheck": "28 Maschen und 2 Ringe. Vorn zählst du 4 Querrippen.", "sAfter": "Die Ringe bleiben bis Türchen 21 auf der Nadel. In den Anleitungen stehen sie nicht mehr extra.", "lines": [["Reihe 1 bis 3, 5 bis 7, 9 bis 11 und 13 bis 15", "Rand A, 24 re, Rand E"], ["Reihe 4, 8, 12 und 16", "Rand A, 24 li, Rand E"]], "end": 28, "rows": [{"id": 107, "row": 1, "rs": true, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 108, "row": 2, "rs": false, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 109, "row": 3, "rs": true, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 110, "row": 4, "rs": false, "text": "Rand A, 24 li, Rand E", "after": 28}, {"id": 111, "row": 5, "rs": true, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 112, "row": 6, "rs": false, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 113, "row": 7, "rs": true, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 114, "row": 8, "rs": false, "text": "Rand A, 24 li, Rand E", "after": 28}, {"id": 115, "row": 9, "rs": true, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 116, "row": 10, "rs": false, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 117, "row": 11, "rs": true, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 118, "row": 12, "rs": false, "text": "Rand A, 24 li, Rand E", "after": 28}, {"id": 119, "row": 13, "rs": true, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 120, "row": 14, "rs": false, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 121, "row": 15, "rs": true, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 122, "row": 16, "rs": false, "text": "Rand A, 24 li, Rand E", "after": 28}], "ends": null, "bow": null, "bindoff": null, "riddle": {"title": "Drei Knäuel im Korb", "typ": "L", "hint": "Fang mit der Position an, die ein Hinweis eindeutig festlegt.", "sol": "Links das weiße Knäuel mit 150 g, in der Mitte das gelbe mit 50 g, rechts das blaue mit 100 g.", "trap": "Läge Weiß in der Mitte, müsste Blau ganz links liegen und 150 g wiegen. Blau wiegt aber 100 g."}}, {"nr": 9, "kniff": "Kleines Perlmuster stricken", "min": "40 bis 50 Min.", "intro": "Aus denselben zwei Maschenarten entsteht eine körnige Fläche. Der Unterschied zu den Rippen liegt im Wechsel von Reihe zu Reihe.", "blick": "Rechts und links versetzen", "steps": [["Die erste Musterreihe", "Wiederhole nach Rand A zwölfmal: 1 re, 1 li. Die letzte Mustermasche ist links. Dann Rand E."], ["Die zweite Reihe versetzt beginnen", "Nach Rand A strickst du die erste Mustermasche links, obwohl sie dir als rechte Masche erscheint. Genau dieser Gegensatz ist gewollt."], ["Den Wechsel fortsetzen", "Wiederhole zwölfmal: 1 li, 1 re. Führe den Faden bei jedem Wechsel zwischen den Spitzen."], ["Die beiden Reihen wiederholen", "Reihe 3 wie Reihe 1, Reihe 4 wie Reihe 2. Rechts über erscheinenden linken, links über erscheinenden rechten Maschen."]], "photos": [{"src": "assets/fotos/t15-entdecken.webp", "cap": "Perlmuster: kleine versetzte Körnchen", "slot": "entdecken"}, {"src": "assets/fotos/t15-schritt-1.webp", "cap": "Das Muster nach den ersten Reihen", "slot": "schritt-1"}, {"src": "assets/fotos/t15-schritt-2.webp", "cap": "Rechte und linke Maschen wechseln", "slot": "schritt-2"}, {"src": "assets/fotos/t15-detail-1.webp", "cap": "Die versetzten Körnchen", "slot": "detail-1"}, {"src": "assets/fotos/t15-detail-2.webp", "cap": "Die Maschen auf der Nadel", "slot": "detail-2"}, {"src": "assets/fotos/t15-ergebnis.webp", "cap": "Beide Seiten sehen körnig aus", "slot": "ergebnis"}], "hakt": [["Es entstehen schmale Rippen.", "Du hast jede Reihe gleich begonnen. Hinreihen beginnen nach Rand A mit 1 re, Rückreihen mit 1 li."], ["Du weißt nicht, welche Reihe folgt.", "Schau auf die erste Mustermasche nach dem Ring. Stricke die entgegengesetzte Maschenart."]], "ww": "Perlmuster sieht aus, als hätte der Schal Gänsehaut. Vor Freude.", "block": "Perlmuster", "sIntro": "Perlmuster: körnig, griffig und auf beiden Seiten schön. Ein Klassiker für Schals.", "sVor": "", "sCheck": "28 Maschen und 2 Ringe.", "sAfter": "Vergleiche mit den Rippen von Türchen 4. Ein anderer Reihenbeginn verändert das ganze Muster.", "lines": [["Alle Hinreihen", "Rand A, 12-mal [1 re, 1 li], Rand E"], ["Alle Rückreihen", "Rand A, 12-mal [1 li, 1 re], Rand E"]], "end": 28, "rows": [{"id": 123, "row": 1, "rs": true, "text": "Rand A, 12-mal [1 re, 1 li], Rand E", "after": 28}, {"id": 124, "row": 2, "rs": false, "text": "Rand A, 12-mal [1 li, 1 re], Rand E", "after": 28}, {"id": 125, "row": 3, "rs": true, "text": "Rand A, 12-mal [1 re, 1 li], Rand E", "after": 28}, {"id": 126, "row": 4, "rs": false, "text": "Rand A, 12-mal [1 li, 1 re], Rand E", "after": 28}, {"id": 127, "row": 5, "rs": true, "text": "Rand A, 12-mal [1 re, 1 li], Rand E", "after": 28}, {"id": 128, "row": 6, "rs": false, "text": "Rand A, 12-mal [1 li, 1 re], Rand E", "after": 28}, {"id": 129, "row": 7, "rs": true, "text": "Rand A, 12-mal [1 re, 1 li], Rand E", "after": 28}, {"id": 130, "row": 8, "rs": false, "text": "Rand A, 12-mal [1 li, 1 re], Rand E", "after": 28}, {"id": 131, "row": 9, "rs": true, "text": "Rand A, 12-mal [1 re, 1 li], Rand E", "after": 28}, {"id": 132, "row": 10, "rs": false, "text": "Rand A, 12-mal [1 li, 1 re], Rand E", "after": 28}, {"id": 133, "row": 11, "rs": true, "text": "Rand A, 12-mal [1 re, 1 li], Rand E", "after": 28}, {"id": 134, "row": 12, "rs": false, "text": "Rand A, 12-mal [1 li, 1 re], Rand E", "after": 28}, {"id": 135, "row": 13, "rs": true, "text": "Rand A, 12-mal [1 re, 1 li], Rand E", "after": 28}, {"id": 136, "row": 14, "rs": false, "text": "Rand A, 12-mal [1 li, 1 re], Rand E", "after": 28}, {"id": 137, "row": 15, "rs": true, "text": "Rand A, 12-mal [1 re, 1 li], Rand E", "after": 28}, {"id": 138, "row": 16, "rs": false, "text": "Rand A, 12-mal [1 li, 1 re], Rand E", "after": 28}], "ends": null, "bow": null, "bindoff": null, "riddle": {"title": "Wortsuche", "typ": "W", "hint": "Fang mit dem längsten Wort an: MUSTER beginnt in Zeile 2.", "sol": "Die Lage aller acht Wörter siehst du im Lösungsgitter.", "trap": ""}}, {"nr": 10, "kniff": "Eine Masche abheben", "min": "35 bis 45 Min.", "intro": "Beim Abheben entsteht keine neue Masche. Du setzt eine vorhandene Schlinge von einer Nadel auf die andere. Aus vielen abgehobenen Maschen entsteht heute ein Muster.", "blick": "Die alte Schlinge wandert mit", "steps": [["Bis zur Hebemasche stricken", "Stricke Rand A und 1 re. Die nächste Masche wird abgehoben. Der Arbeitsfaden bleibt hinter der Arbeit."], ["Wie zum Linksstricken einstechen", "Führe die rechte Nadel von rechts nach links in die nächste Masche, wie bei einer linken Masche. Hole aber keinen Faden."], ["Die Schlinge übertragen", "Schiebe die Masche unverändert auf die rechte Nadel. Ziehe keine neue Schlinge hindurch."], ["Weiterstricken", "Stricke 2 re. Hinter der abgehobenen Masche liegt ein kurzer Querfaden. Lass ihn locker, sonst zieht sich der Schal zusammen."]], "photos": [{"src": "assets/fotos/t07-entdecken.webp", "cap": "Eine Masche wird nur übertragen", "slot": "entdecken"}, {"src": "assets/fotos/t07-schritt-1.webp", "cap": "Den Arbeitsfaden hinten halten", "slot": "schritt-1"}, {"src": "assets/fotos/t07-schritt-2.webp", "cap": "Die vorhandene Schlinge erfassen", "slot": "schritt-2"}, {"src": "assets/fotos/t07-detail-1.webp", "cap": "Die Schlinge ohne neuen Faden übertragen", "slot": "detail-1"}, {"src": "assets/fotos/t07-detail-2.webp", "cap": "Mit der nächsten Masche weiterarbeiten", "slot": "detail-2"}, {"src": "assets/fotos/t07-ergebnis.webp", "cap": "Abgehobene Maschen wirken etwas länger", "slot": "ergebnis"}], "hakt": [["Eine zusätzliche Schlinge liegt auf der Nadel.", "Du hast möglicherweise den Arbeitsfaden mitgenommen. Beim Abheben entsteht keine neue Schlinge."], ["Die Stelle zieht sich zusammen.", "Der Faden hinter der abgehobenen Masche ist zu kurz. Verteile die Maschen auf dem Schaft, bevor du weiterstrickst."]], "ww": "Abheben heißt hier ausnahmsweise nicht, dass jemand die Nerven verliert.", "block": "Hebemaschen", "sIntro": "Hebemaschen: Acht senkrechte Linien aus langen Maschen laufen über diesen Abschnitt.", "sVor": "1 abh heißt hier: wie zum Linksstricken abheben, Faden hinter der Arbeit. In der Rückreihe strickst du alle Mustermaschen links, auch die abgehobenen.", "sCheck": "28 Maschen und 2 Ringe. Pro Hinreihe hebst du 8 Mustermaschen ab.", "sAfter": "Abheben ohne Angabe gibt es nicht. Heute hieß es: wie zum Linksstricken, Faden hinten.", "lines": [["Alle Hinreihen", "Rand A, 1 re, 7-mal [1 abh, 2 re], 1 abh, 1 re, Rand E"], ["Alle Rückreihen", "Rand A, 24 li, Rand E"]], "end": 28, "rows": [{"id": 139, "row": 1, "rs": true, "text": "Rand A, 1 re, 7-mal [1 abh, 2 re], 1 abh, 1 re, Rand E", "after": 28}, {"id": 140, "row": 2, "rs": false, "text": "Rand A, 24 li, Rand E", "after": 28}, {"id": 141, "row": 3, "rs": true, "text": "Rand A, 1 re, 7-mal [1 abh, 2 re], 1 abh, 1 re, Rand E", "after": 28}, {"id": 142, "row": 4, "rs": false, "text": "Rand A, 24 li, Rand E", "after": 28}, {"id": 143, "row": 5, "rs": true, "text": "Rand A, 1 re, 7-mal [1 abh, 2 re], 1 abh, 1 re, Rand E", "after": 28}, {"id": 144, "row": 6, "rs": false, "text": "Rand A, 24 li, Rand E", "after": 28}, {"id": 145, "row": 7, "rs": true, "text": "Rand A, 1 re, 7-mal [1 abh, 2 re], 1 abh, 1 re, Rand E", "after": 28}, {"id": 146, "row": 8, "rs": false, "text": "Rand A, 24 li, Rand E", "after": 28}, {"id": 147, "row": 9, "rs": true, "text": "Rand A, 1 re, 7-mal [1 abh, 2 re], 1 abh, 1 re, Rand E", "after": 28}, {"id": 148, "row": 10, "rs": false, "text": "Rand A, 24 li, Rand E", "after": 28}, {"id": 149, "row": 11, "rs": true, "text": "Rand A, 1 re, 7-mal [1 abh, 2 re], 1 abh, 1 re, Rand E", "after": 28}, {"id": 150, "row": 12, "rs": false, "text": "Rand A, 24 li, Rand E", "after": 28}, {"id": 151, "row": 13, "rs": true, "text": "Rand A, 1 re, 7-mal [1 abh, 2 re], 1 abh, 1 re, Rand E", "after": 28}, {"id": 152, "row": 14, "rs": false, "text": "Rand A, 24 li, Rand E", "after": 28}, {"id": 153, "row": 15, "rs": true, "text": "Rand A, 1 re, 7-mal [1 abh, 2 re], 1 abh, 1 re, Rand E", "after": 28}, {"id": 154, "row": 16, "rs": false, "text": "Rand A, 24 li, Rand E", "after": 28}], "ends": null, "bow": null, "bindoff": null, "riddle": {"title": "Abgehoben", "typ": "R", "hint": "Wie viele der 16 Reihen sind Hinreihen?", "sol": "80 Maschen: 8 Hinreihen mit je 8 Mustermaschen ergeben 64, dazu 16 Randmaschen.", "trap": "Wer 16 mal 8 rechnet, vergisst, dass die Mustermaschen nur in den Hinreihen abgehoben werden. Und die Randmaschen fallen gern unter den Tisch."}}, {"nr": 11, "kniff": "Zwei Maschen zusammenstricken", "min": "35 bis 45 Min.", "intro": "Mit einer Abnahme verringerst du die Maschenzahl. Heute werden zwei Maschen in der Mitte gemeinsam rechts gestrickt.", "blick": "Aus zwei wird eine", "steps": [["Die beiden Maschen vorbereiten", "Stricke in Reihe 9 Rand A und 11 re. Schiebe die nächsten zwei Maschen nah an die linke Spitze. Der Faden liegt hinten."], ["Durch beide einstechen", "Stich von vorn zuerst durch die zweite Masche von der Spitze aus und weiter durch die erste. Beide bleiben noch links."], ["Eine neue Schlinge durchholen", "Erfasse den Arbeitsfaden und ziehe ihn durch beide Maschen nach vorn. Es entsteht eine einzige neue Schlinge."], ["Beide alten Maschen abgleiten lassen", "Lass beide gemeinsam von der linken Spitze gleiten. Stricke 11 re und Rand E. Die Reihe hat jetzt 27 Maschen."]], "photos": [{"src": "assets/fotos/t08-entdecken.webp", "cap": "Aus zwei Maschen wird eine", "slot": "entdecken"}, {"src": "assets/fotos/t08-schritt-1.webp", "cap": "Die beiden nächsten Maschen", "slot": "schritt-1"}, {"src": "assets/fotos/t08-schritt-2.webp", "cap": "Beide Schlingen auf einer Nadelspitze", "slot": "schritt-2"}, {"src": "assets/fotos/t08-detail-1.webp", "cap": "Die Schlingen beim Durchholen", "slot": "detail-1"}, {"src": "assets/fotos/t08-ergebnis.webp", "cap": "Glatte Fläche: So sieht dieser Abschnitt aus", "slot": "ergebnis"}], "hakt": [["Die Nadel geht kaum hindurch.", "Schiebe beide Maschen näher zur Spitze und entspanne den Faden. Drücke die Nadel nicht mit Kraft hindurch."], ["Du hast weiter 28 Maschen.", "Prüfe, ob du wirklich beide Maschen zusammen gestrickt hast. Mit nur einer fand keine Abnahme statt."]], "ww": "Zwei Maschen zusammenstricken: das einzige Zusammenlegen, das ganz ohne Diskussion klappt.", "block": "Glatt mit Abnahme", "sIntro": "Ein glatter Abschnitt mit einer einzigen Abnahme in der Mitte. Morgen kommt die Masche zurück, versprochen.", "sVor": "", "sCheck": "27 Maschen und 2 Ringe. Ja, 27. Das stimmt so.", "sAfter": "In vielen Anleitungen steht dafür „2 M re zusstr“. Dahinter steckt genau die Bewegung von heute.", "lines": [["Reihe 1, 3, 5 und 7", "Rand A, 24 re, Rand E"], ["Reihe 2, 4, 6 und 8", "Rand A, 24 li, Rand E"], ["Reihe 9", "Rand A, 11 re, 2 re zus, 11 re, Rand E"], ["Reihe 10, 12, 14 und 16", "Rand A, 23 li, Rand E"], ["Reihe 11, 13 und 15", "Rand A, 23 re, Rand E"]], "end": 27, "rows": [{"id": 155, "row": 1, "rs": true, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 156, "row": 2, "rs": false, "text": "Rand A, 24 li, Rand E", "after": 28}, {"id": 157, "row": 3, "rs": true, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 158, "row": 4, "rs": false, "text": "Rand A, 24 li, Rand E", "after": 28}, {"id": 159, "row": 5, "rs": true, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 160, "row": 6, "rs": false, "text": "Rand A, 24 li, Rand E", "after": 28}, {"id": 161, "row": 7, "rs": true, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 162, "row": 8, "rs": false, "text": "Rand A, 24 li, Rand E", "after": 28}, {"id": 163, "row": 9, "rs": true, "text": "Rand A, 11 re, 2 re zus, 11 re, Rand E", "after": 27}, {"id": 164, "row": 10, "rs": false, "text": "Rand A, 23 li, Rand E", "after": 27}, {"id": 165, "row": 11, "rs": true, "text": "Rand A, 23 re, Rand E", "after": 27}, {"id": 166, "row": 12, "rs": false, "text": "Rand A, 23 li, Rand E", "after": 27}, {"id": 167, "row": 13, "rs": true, "text": "Rand A, 23 re, Rand E", "after": 27}, {"id": 168, "row": 14, "rs": false, "text": "Rand A, 23 li, Rand E", "after": 27}, {"id": 169, "row": 15, "rs": true, "text": "Rand A, 23 re, Rand E", "after": 27}, {"id": 170, "row": 16, "rs": false, "text": "Rand A, 23 li, Rand E", "after": 27}], "ends": null, "bow": null, "bindoff": null, "riddle": {"title": "Finde den Fehler", "typ": "F", "hint": "Zähle für jede Zeile, wie viele Maschen sie verbraucht. Ein Umschlag verbraucht keine, 2 re zus verbraucht zwei.", "sol": "D.", "trap": "D verbraucht 2 + 1 + 24 + 1 + 2 = 30 Maschen. A geht auf, endet aber mit 27 Maschen. Das ist kein Fehler, sondern eine Abnahme."}}, {"nr": 12, "kniff": "Einen Umschlag arbeiten", "min": "35 bis 45 Min.", "intro": "Ein Umschlag legt eine neue Schlinge auf die Nadel, ohne eine Masche zu verbrauchen. Das kleine Loch darunter ist gewollt. Heute holt er dir die Masche von gestern zurück.", "blick": "Eine zusätzliche Schlinge", "steps": [["Bis zur Mitte stricken", "Stricke in Reihe 1 Rand A und 11 re. Die Abnahme von gestern liegt jetzt direkt vor dir."], ["Den Faden nach vorn holen", "Führe den Arbeitsfaden zwischen den Nadelspitzen nach vorn, wie in Türchen 4."], ["Über die rechte Nadel legen", "Führe den Faden über die rechte Nadel nach hinten. Eine zusätzliche Schlinge liegt auf der Nadel."], ["Weiterstricken", "Stricke 12 re und Rand E. Du hast wieder 28 Maschen. In der Rückreihe strickst du den Umschlag ganz normal links."]], "photos": [{"src": "assets/fotos/t09-entdecken.webp", "cap": "Ein kleines Loch: der Umschlag", "slot": "entdecken"}, {"src": "assets/fotos/t09-schritt-1.webp", "cap": "Bis zur Stelle stricken", "slot": "schritt-1"}, {"src": "assets/fotos/t09-schritt-2.webp", "cap": "Der Faden wird umgelegt", "slot": "schritt-2"}, {"src": "assets/fotos/t09-detail-1.webp", "cap": "Die zusätzliche Schlinge", "slot": "detail-1"}, {"src": "assets/fotos/t09-detail-2.webp", "cap": "Der Umschlag neben den Maschen", "slot": "detail-2"}, {"src": "assets/fotos/t09-ergebnis.webp", "cap": "Das Loch bleibt sichtbar", "slot": "ergebnis"}], "hakt": [["Es sind zwei zusätzliche Schlingen.", "Der Faden wurde vermutlich zweimal um die Nadel gelegt. Du brauchst nur eine."], ["Das Loch ist kaum zu sehen.", "Prüfe, ob du den Umschlag in der Rückreihe verdreht gestrickt hast. Stich normal wie zum Linksstricken ein."]], "ww": "Ein Loch im Strickzeug heißt Fehler. Elf Löcher in einer Reihe heißen Muster.", "block": "Lochmuster", "sIntro": "Lochmuster: drei Reihen kleiner Löcher. In einer Lochreihe folgt auf jeden Umschlag sofort eine Abnahme, deshalb bleibt die Zahl gleich.", "sVor": "", "sCheck": "28 Maschen und 2 Ringe. Die 28 stimmt wieder.", "sAfter": "Elf Umschläge, elf Abnahmen: In einer Lochreihe hebt sich beides auf.", "lines": [["Reihe 1", "Rand A, 11 re, U, 12 re, Rand E"], ["Alle Rückreihen", "Rand A, 24 li, Rand E"], ["Reihe 3, 7, 11 und 15", "Rand A, 24 re, Rand E"], ["Reihe 5, 9 und 13", "Rand A, 1 re, 11-mal [U, 2 re zus], 1 re, Rand E"]], "end": 28, "rows": [{"id": 171, "row": 1, "rs": true, "text": "Rand A, 11 re, U, 12 re, Rand E", "after": 28}, {"id": 172, "row": 2, "rs": false, "text": "Rand A, 24 li, Rand E", "after": 28}, {"id": 173, "row": 3, "rs": true, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 174, "row": 4, "rs": false, "text": "Rand A, 24 li, Rand E", "after": 28}, {"id": 175, "row": 5, "rs": true, "text": "Rand A, 1 re, 11-mal [U, 2 re zus], 1 re, Rand E", "after": 28}, {"id": 176, "row": 6, "rs": false, "text": "Rand A, 24 li, Rand E", "after": 28}, {"id": 177, "row": 7, "rs": true, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 178, "row": 8, "rs": false, "text": "Rand A, 24 li, Rand E", "after": 28}, {"id": 179, "row": 9, "rs": true, "text": "Rand A, 1 re, 11-mal [U, 2 re zus], 1 re, Rand E", "after": 28}, {"id": 180, "row": 10, "rs": false, "text": "Rand A, 24 li, Rand E", "after": 28}, {"id": 181, "row": 11, "rs": true, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 182, "row": 12, "rs": false, "text": "Rand A, 24 li, Rand E", "after": 28}, {"id": 183, "row": 13, "rs": true, "text": "Rand A, 1 re, 11-mal [U, 2 re zus], 1 re, Rand E", "after": 28}, {"id": 184, "row": 14, "rs": false, "text": "Rand A, 24 li, Rand E", "after": 28}, {"id": 185, "row": 15, "rs": true, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 186, "row": 16, "rs": false, "text": "Rand A, 24 li, Rand E", "after": 28}], "ends": null, "bow": null, "bindoff": null, "riddle": {"title": "Im Strickcafé", "typ": "L", "hint": "Zeichne drei Tische nebeneinander und trage ein, was sicher ist.", "sol": "Bärbel sitzt an Tisch 1 mit Perlmuster, Elif an Tisch 2 mit Lochmuster, Konrad an Tisch 3 mit Rippen.", "trap": "Konrad kann nicht an Tisch 1 sitzen, sonst gäbe es keinen niedrigeren Tisch für das Perlmuster."}}, {"nr": 13, "kniff": "Eine offene Masche sichern", "min": "35 bis 45 Min.", "intro": "Eine heruntergerutschte Masche ist kein Drama. Heute lässt du sie absichtlich fallen und fängst sie sicher auf. Die Mutprobe im Advent.", "blick": "Erst auffangen, dann reparieren", "steps": [["Eine Masche freilegen", "Stricke in Reihe 15 Rand A und 11 re. Schiebe die nächste Masche vorsichtig von der linken Spitze und halte sie mit den Fingern fest."], ["Nur eine Reihe lösen", "Lockere die Schlinge, bis sie sich eine Reihe tiefer auflöst. Halte die frei werdende Schlinge sofort fest. Darüber liegt jetzt ein loser Querfaden."], ["Den Markierer einhängen", "Öffne den verschließbaren Markierer und führe ihn durch die ganze offene Schlinge, ohne einen Fadenschenkel zu teilen."], ["Sicher ablegen", "Schließe den Markierer. Lass den Querfaden frei. Leg den Schal so ab, dass keine Masche von den Nadeln rutscht."]], "photos": [{"src": "assets/fotos/t18-entdecken.webp", "cap": "Geübt an einer losen Garnschlinge: der verschließbare Markierer", "slot": "entdecken"}, {"src": "assets/fotos/t18-schritt-1.webp", "cap": "Die lose Schlinge offen halten", "slot": "schritt-1"}, {"src": "assets/fotos/t18-schritt-2.webp", "cap": "Markierer und Schlinge", "slot": "schritt-2"}, {"src": "assets/fotos/t18-detail-1.webp", "cap": "Durch die Öffnung der Schlinge führen", "slot": "detail-1"}, {"src": "assets/fotos/t18-detail-2.webp", "cap": "Den Markierer vollständig schließen", "slot": "detail-2"}, {"src": "assets/fotos/t18-ergebnis.webp", "cap": "Die ganze Schlinge sitzt im Markierer", "slot": "ergebnis"}], "hakt": [["Die Schlinge läuft weiter nach unten.", "Halte sofort an und fange die unterste offene Schlinge mit der Häkelnadel auf."], ["Der Markierer steckt nur im Faden.", "Er muss durch die Öffnung der ganzen Schlinge laufen. Durchstochene Fasern halten nichts."]], "ww": "Mut ist, eine Masche absichtlich fallen zu lassen. Und dabei leise zu bleiben.", "block": "Glatt mit Rettungsübung", "sIntro": "Ein glatter Abschnitt, in dem heute eine Masche fallen darf. Morgen holst du sie wieder hoch.", "sVor": "", "sCheck": "Auf den Nadeln 27 Maschen: 13 rechts, 14 links. Dazu 1 Schlinge im Markierer.", "sAfter": "Leg den Schal heute Abend so weg. Die Masche wartet im Markierer bis morgen.", "lines": [["Alle Hinreihen", "Rand A, 24 re, Rand E"], ["Alle Rückreihen", "Rand A, 24 li, Rand E"]], "end": 28, "rows": [{"id": 187, "row": 1, "rs": true, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 188, "row": 2, "rs": false, "text": "Rand A, 24 li, Rand E", "after": 28}, {"id": 189, "row": 3, "rs": true, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 190, "row": 4, "rs": false, "text": "Rand A, 24 li, Rand E", "after": 28}, {"id": 191, "row": 5, "rs": true, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 192, "row": 6, "rs": false, "text": "Rand A, 24 li, Rand E", "after": 28}, {"id": 193, "row": 7, "rs": true, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 194, "row": 8, "rs": false, "text": "Rand A, 24 li, Rand E", "after": 28}, {"id": 195, "row": 9, "rs": true, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 196, "row": 10, "rs": false, "text": "Rand A, 24 li, Rand E", "after": 28}, {"id": 197, "row": 11, "rs": true, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 198, "row": 12, "rs": false, "text": "Rand A, 24 li, Rand E", "after": 28}, {"id": 199, "row": 13, "rs": true, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 200, "row": 14, "rs": false, "text": "Rand A, 24 li, Rand E", "after": 28}, {"id": null, "row": 15, "rs": true, "text": "Rand A, 11 re. Dann die nächste Masche fallen lassen und mit dem Markierer sichern, wie im Kniff. Hier hörst du heute auf.", "after": null, "partial": true}], "ends": null, "bow": null, "bindoff": null, "riddle": {"title": "Buchstabensalat", "typ": "B", "hint": "Ein Wort sichert die gefallene Masche, eins holt sie hoch.", "sol": "SCHLINGE, MARKIERER, FADEN, HAKEN.", "trap": ""}}, {"nr": 14, "kniff": "Eine rechte Masche hochholen", "min": "35 bis 45 Min.", "intro": "Aus der gesicherten Schlinge und dem Querfaden darüber wird wieder eine ganze Masche. Du arbeitest von der Vorderseite aus.", "blick": "Den Querfaden durch die Schlinge ziehen", "steps": [["Die Schlinge aufnehmen", "Stich mit der Häkelnadel von vorn nach hinten durch die gesicherte Schlinge. Erst wenn sie auf der Häkelnadel liegt, entfernst du den Markierer."], ["Den Querfaden erfassen", "Der lose Querfaden liegt hinter der Häkelnadel, direkt über der Schlinge. Hole ihn mit dem Haken."], ["Eine neue Schlinge bilden", "Ziehe den Querfaden durch die alte Schlinge nach vorn. Die alte gleitet vom Haken, die neue bleibt darauf."], ["Zurück auf die Nadel", "Setze die neue Schlinge vorn auf die linke Nadel, rechtes Maschenglied vorn. Dann strickst du die Reihe zu Ende."]], "photos": [{"src": "assets/fotos/t19-entdecken.webp", "cap": "Die gesicherte Schlinge, darüber der Querfaden", "slot": "entdecken"}, {"src": "assets/fotos/t19-schritt-1.webp", "cap": "Der Haken in der Schlinge", "slot": "schritt-1"}, {"src": "assets/fotos/t19-schritt-2.webp", "cap": "Den Querfaden erfassen", "slot": "schritt-2"}, {"src": "assets/fotos/t19-detail-1.webp", "cap": "Die neue Schlinge entsteht", "slot": "detail-1"}, {"src": "assets/fotos/t19-detail-2.webp", "cap": "Die Stricknadel übernimmt die Schlinge", "slot": "detail-2"}, {"src": "assets/fotos/t19-ergebnis.webp", "cap": "Die gerettete Masche: ein offenes V", "slot": "ergebnis"}], "hakt": [["Unter der neuen Masche bleibt ein Loch.", "Möglicherweise hast du einen Querfaden übersprungen. Sichere die Schlinge und prüfe noch einmal."], ["Die reparierte Masche ist verdreht.", "Prüfe ihre Lage auf der linken Nadel. Das rechte Maschenglied muss vorn liegen."]], "ww": "Eine gerettete Masche sieht genauso aus wie alle anderen. Nur du weißt Bescheid.", "block": "Rippen 1:1 nach der Rettung", "sIntro": "Erst die Rettung, dann wieder Rippen. Wer genau hinsieht, findet die gerettete Masche nicht mehr.", "sVor": "", "sCheck": "Nach Reihe 15 wieder 28 Maschen und 2 Ringe.", "sAfter": "Ab heute weißt du: Eine gefallene Masche ist in fünf Minuten wieder da.", "lines": [["Reihe 16", "Rand A, 24 li, Rand E"], ["Reihe 17 bis 30", "Rand A, 12-mal [1 re, 1 li], Rand E"]], "end": 28, "rows": [{"id": 201, "row": 15, "rs": true, "text": "Reihe 15 zu Ende stricken: die hochgeholte Masche re, dann 12 re, Rand E", "after": 28}, {"id": 202, "row": 16, "rs": false, "text": "Rand A, 24 li, Rand E", "after": 28}, {"id": 203, "row": 17, "rs": true, "text": "Rand A, 12-mal [1 re, 1 li], Rand E", "after": 28}, {"id": 204, "row": 18, "rs": false, "text": "Rand A, 12-mal [1 re, 1 li], Rand E", "after": 28}, {"id": 205, "row": 19, "rs": true, "text": "Rand A, 12-mal [1 re, 1 li], Rand E", "after": 28}, {"id": 206, "row": 20, "rs": false, "text": "Rand A, 12-mal [1 re, 1 li], Rand E", "after": 28}, {"id": 207, "row": 21, "rs": true, "text": "Rand A, 12-mal [1 re, 1 li], Rand E", "after": 28}, {"id": 208, "row": 22, "rs": false, "text": "Rand A, 12-mal [1 re, 1 li], Rand E", "after": 28}, {"id": 209, "row": 23, "rs": true, "text": "Rand A, 12-mal [1 re, 1 li], Rand E", "after": 28}, {"id": 210, "row": 24, "rs": false, "text": "Rand A, 12-mal [1 re, 1 li], Rand E", "after": 28}, {"id": 211, "row": 25, "rs": true, "text": "Rand A, 12-mal [1 re, 1 li], Rand E", "after": 28}, {"id": 212, "row": 26, "rs": false, "text": "Rand A, 12-mal [1 re, 1 li], Rand E", "after": 28}, {"id": 213, "row": 27, "rs": true, "text": "Rand A, 12-mal [1 re, 1 li], Rand E", "after": 28}, {"id": 214, "row": 28, "rs": false, "text": "Rand A, 12-mal [1 re, 1 li], Rand E", "after": 28}, {"id": 215, "row": 29, "rs": true, "text": "Rand A, 12-mal [1 re, 1 li], Rand E", "after": 28}, {"id": 216, "row": 30, "rs": false, "text": "Rand A, 12-mal [1 re, 1 li], Rand E", "after": 28}], "ends": null, "bow": null, "bindoff": null, "riddle": {"title": "Teepause", "typ": "R", "hint": "Wie viele Maschen sind es zusammen? Und wie viele Pausen liegen wirklich zwischen Reihe 1 und Reihe 15?", "sol": "23 Minuten: 420 Maschen brauchen 21 Minuten, dazu zwei Teepausen.", "trap": "Nach Reihe 15 ist Schluss. Die dritte Pause zählt deshalb nicht mehr mit."}}, {"nr": 15, "kniff": "Am Rand die Farbe wechseln", "min": "30 bis 40 Min.", "intro": "Ein Farbwechsel am Reihenanfang braucht keinen dicken Knoten. Die offenen Enden werden später einzeln vernäht.", "blick": "Mit dem neuen Faden beginnen", "steps": [["Den alten Faden ablegen", "Die letzte Reihe von gestern ist fertig. Schneide Farbe A mit etwa 15 cm Rest ab. Die volle Nadel liegt links."], ["Den neuen Faden bereitlegen", "Lass bei Farbe B etwa 15 cm Anfang frei. Nur der lange Teil zum Knäuel läuft über deinen Zeigefinger."], ["Die erste Masche neu stricken", "In dieser ersten Reihe hebst du nicht ab: Stich in die erste Masche wie zum Rechtsstricken und hole eine Schlinge aus Farbe B. Halte das kurze Ende fest."], ["Mit Farbe B weiterarbeiten", "Stricke die Reihe zu Ende. Der kurze Anfangsfaden wird nicht mitgestrickt. Ab Reihe 2 gilt wieder Rand A."]], "photos": [{"src": "assets/fotos/t17-entdecken.webp", "cap": "Ein Streifen in der zweiten Farbe", "slot": "entdecken"}, {"src": "assets/fotos/t17-schritt-1.webp", "cap": "Der Reihenanfang vor dem Farbwechsel", "slot": "schritt-1"}, {"src": "assets/fotos/t17-schritt-2.webp", "cap": "Den neuen Arbeitsfaden bereithalten", "slot": "schritt-2"}, {"src": "assets/fotos/t17-detail-1.webp", "cap": "Die erste Masche mit der neuen Farbe", "slot": "detail-1"}, {"src": "assets/fotos/t17-detail-2.webp", "cap": "Die neue Farbe über die ganze Reihe", "slot": "detail-2"}, {"src": "assets/fotos/t17-ergebnis.webp", "cap": "Kraus rechts mit Farbstreifen", "slot": "ergebnis"}], "hakt": [["Die erste Masche wird riesig.", "Halte das kurze Ende während der ersten Maschen fest. Später ziehst du die Schlinge sanft an diesem Ende zurecht."], ["Es liegen doppelte Schlingen auf der Nadel.", "Du hast Anfangs- und Arbeitsfaden zusammen benutzt. Gestrickt wird nur mit dem Faden zum Knäuel."]], "ww": "Neue Farbe, neues Glück. Und zwei neue Fadenenden.", "block": "Streifen in Farbe B", "sIntro": "Ein Streifen in Farbe B. Er liegt fast genau zwischen den Türchen, an denen du gestartet bist und an denen du fertig wirst.", "sVor": "Lass alle Fadenenden hängen. In Türchen 22 vernähst du sie auf einmal.", "sCheck": "28 Maschen und 2 Ringe. Alle in Farbe B.", "sAfter": "Ein Farbwechsel kostet keine Masche. Nur zwei Fadenenden.", "lines": [["Reihe 1", "28 re"], ["Reihe 2 bis 14", "Rand A, 24 re, Rand E"]], "end": 28, "rows": [{"id": 217, "row": 1, "rs": true, "text": "28 re", "after": 28}, {"id": 218, "row": 2, "rs": false, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 219, "row": 3, "rs": true, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 220, "row": 4, "rs": false, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 221, "row": 5, "rs": true, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 222, "row": 6, "rs": false, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 223, "row": 7, "rs": true, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 224, "row": 8, "rs": false, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 225, "row": 9, "rs": true, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 226, "row": 10, "rs": false, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 227, "row": 11, "rs": true, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 228, "row": 12, "rs": false, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 229, "row": 13, "rs": true, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 230, "row": 14, "rs": false, "text": "Rand A, 24 re, Rand E", "after": 28}], "ends": null, "bow": null, "bindoff": null, "riddle": {"title": "Wortsuche", "typ": "W", "hint": "Fang mit dem längsten Wort an: STREIFEN beginnt in Zeile 3.", "sol": "Die Lage aller acht Wörter siehst du im Lösungsgitter.", "trap": ""}}, {"nr": 16, "kniff": "Maschen auf einen Faden legen", "min": "40 bis 50 Min.", "intro": "Halbzeit. Heute legst du deinen Schal für ein paar Minuten von der Nadel und probierst ihn an.", "blick": "Die Nadel für eine Pause freimachen", "steps": [["Die erste Schlinge erfassen", "Fädle etwa 80 cm glatten Hilfsfaden in die Wollnadel. Stich wie zum Linksstricken durch die erste Masche und ziehe den Faden hindurch."], ["Erst sichern, dann abgleiten lassen", "Lass jede Masche erst von der Stricknadel gleiten, wenn der Hilfsfaden durch sie läuft. Die Ringe nimmst du ab und legst sie beiseite."], ["Die Enden verbinden", "Zähle 28 Schlingen auf dem Hilfsfaden und verknote die Enden locker. Jetzt darfst du den Schal umlegen."], ["Die Maschen wieder aufnehmen", "Führe die Nadel entlang des Hilfsfadens durch alle Maschen, rechtes Maschenglied vorn, sodass der Arbeitsfaden an der ersten Masche hängt. Setz die Ringe wieder ein. Dann ziehst du den Hilfsfaden heraus."]], "photos": [{"src": "assets/fotos/t21-entdecken.webp", "cap": "Stillgelegte Maschen auf dem Hilfsfaden", "slot": "entdecken"}, {"src": "assets/fotos/t21-schritt-1.webp", "cap": "Wollnadel und Hilfsfaden in der Schlinge", "slot": "schritt-1"}, {"src": "assets/fotos/t21-schritt-2.webp", "cap": "Die gesicherten Maschen ohne Stricknadel", "slot": "schritt-2"}, {"src": "assets/fotos/t21-detail-1.webp", "cap": "Die Schlingen auf dem Hilfsfaden prüfen", "slot": "detail-1"}, {"src": "assets/fotos/t21-detail-2.webp", "cap": "Die Stricknadel wieder einführen", "slot": "detail-2"}, {"src": "assets/fotos/t21-ergebnis.webp", "cap": "Die Maschen ruhen sicher auf dem Faden", "slot": "ergebnis"}], "hakt": [["Eine Masche ist sehr eng.", "Ziehe die Schlingen nicht am Hilfsfaden zusammen. Zum Aufnehmen hilft eine dünnere Nadel."], ["Eine Schlinge bleibt neben der Nadel.", "Lass den Hilfsfaden unbedingt liegen, nimm die Masche auf und zähle, bevor du ihn entfernst."]], "ww": "Halbzeit: lang genug, um ihn stolz herumzuzeigen. Zu kurz, um ihn zu tragen.", "block": "Glatt in Farbe A", "sIntro": "Zurück zu Farbe A mit einer glatten Fläche. Danach kommt die Anprobe.", "sVor": "Schneide Farbe B mit 15 cm Rest ab. Reihe 1 beginnt in Farbe A ohne Abheben, wie gestern.", "sCheck": "28 Maschen und 2 Ringe. Vor der Anprobe: 28 Schlingen auf dem Hilfsfaden.", "sAfter": "Drei Viertel deines Schals sind gestrickt. Wenn du ihn umlegst, siehst du schon, wie er wird.", "lines": [["Reihe 1", "28 re"], ["Alle Rückreihen", "Rand A, 24 li, Rand E"], ["Reihe 3, 5, 7, 9, 11, 13 und 15", "Rand A, 24 re, Rand E"]], "end": 28, "rows": [{"id": 231, "row": 1, "rs": true, "text": "28 re", "after": 28}, {"id": 232, "row": 2, "rs": false, "text": "Rand A, 24 li, Rand E", "after": 28}, {"id": 233, "row": 3, "rs": true, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 234, "row": 4, "rs": false, "text": "Rand A, 24 li, Rand E", "after": 28}, {"id": 235, "row": 5, "rs": true, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 236, "row": 6, "rs": false, "text": "Rand A, 24 li, Rand E", "after": 28}, {"id": 237, "row": 7, "rs": true, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 238, "row": 8, "rs": false, "text": "Rand A, 24 li, Rand E", "after": 28}, {"id": 239, "row": 9, "rs": true, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 240, "row": 10, "rs": false, "text": "Rand A, 24 li, Rand E", "after": 28}, {"id": 241, "row": 11, "rs": true, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 242, "row": 12, "rs": false, "text": "Rand A, 24 li, Rand E", "after": 28}, {"id": 243, "row": 13, "rs": true, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 244, "row": 14, "rs": false, "text": "Rand A, 24 li, Rand E", "after": 28}, {"id": 245, "row": 15, "rs": true, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 246, "row": 16, "rs": false, "text": "Rand A, 24 li, Rand E", "after": 28}], "ends": null, "bow": null, "bindoff": null, "riddle": {"title": "Drei Schals", "typ": "L", "hint": "Eine Tabelle mit Längen und Farben hilft. Setze zuerst die Länge, die ein Hinweis direkt nennt.", "sol": "Ottilie: 120 cm in Senf. Malte: 150 cm in Beere. Rosa: 180 cm in Petrol.", "trap": "Rosa kann nicht Senf nehmen, das hat Ottilie. Beere ist ausgeschlossen, also Petrol, und Petrol ist der längste Schal."}}, {"nr": 17, "kniff": "Eine Maschenprobe messen", "min": "35 bis 45 Min.", "intro": "Wie lang wird dein Schal, und reicht die Wolle? Heute misst du nach und rechnest einmal kurz, bevor du weiterstrickst.", "blick": "Zehn Zentimeter in der Mitte", "steps": [["Den Schal entspannt hinlegen", "Lege den Schal glatt auf den Tisch, Vorderseite nach oben. Ziehe ihn nicht in Form, während du misst."], ["Waagerecht messen", "Lege das Lineal quer über die glatte Fläche von gestern. Zähle die V-Maschen auf 10 cm. Rand und Kanten bleiben außerhalb."], ["Die Länge messen", "Miss den Schal von der Anschlagkante bis zur Nadel. Lass ihn dabei flach liegen."], ["Beide Werte notieren", "Schreib dir Maschen auf 10 cm und die Länge auf. Unten auf der Schal-Seite rechnest du damit weiter."]], "photos": [{"src": "assets/fotos/t22-entdecken.webp", "cap": "Lineal, Notizbuch, ein ruhiger Tisch", "slot": "entdecken"}, {"src": "assets/fotos/t22-schritt-1.webp", "cap": "Die Fläche flach hinlegen", "slot": "schritt-1"}, {"src": "assets/fotos/t22-schritt-2.webp", "cap": "Waagerecht über 10 cm messen", "slot": "schritt-2"}, {"src": "assets/fotos/t22-detail-1.webp", "cap": "Senkrecht messen", "slot": "detail-1"}, {"src": "assets/fotos/t22-detail-2.webp", "cap": "Beide Werte aufschreiben", "slot": "detail-2"}, {"src": "assets/fotos/t22-ergebnis.webp", "cap": "Die Werte gehören ins Notizbuch", "slot": "ergebnis"}], "hakt": [["Am Rand kommt eine andere Zahl heraus.", "Randmaschen sind oft breiter oder schmaler. Miss in der Mitte der Fläche."], ["Die Wolle wird knapp.", "Stricke in Türchen 20 nur 8 statt 16 Reihen. Der Schal wird dann ein paar Zentimeter kürzer."]], "ww": "Strickerinnen glauben an Maschenproben wie an den Wetterbericht: grundsätzlich ja, im Zweifel selbst nachsehen.", "block": "Querrippen", "sIntro": "Noch einmal Querrippen. Vorher kommt die Rechnung.", "sVor": "", "sCheck": "28 Maschen und 2 Ringe.", "sAfter": "", "lines": [["Reihe 1 bis 3, 5 bis 7, 9 bis 11 und 13 bis 15", "Rand A, 24 re, Rand E"], ["Reihe 4, 8, 12 und 16", "Rand A, 24 li, Rand E"]], "end": 28, "rows": [{"id": 247, "row": 1, "rs": true, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 248, "row": 2, "rs": false, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 249, "row": 3, "rs": true, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 250, "row": 4, "rs": false, "text": "Rand A, 24 li, Rand E", "after": 28}, {"id": 251, "row": 5, "rs": true, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 252, "row": 6, "rs": false, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 253, "row": 7, "rs": true, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 254, "row": 8, "rs": false, "text": "Rand A, 24 li, Rand E", "after": 28}, {"id": 255, "row": 9, "rs": true, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 256, "row": 10, "rs": false, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 257, "row": 11, "rs": true, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 258, "row": 12, "rs": false, "text": "Rand A, 24 li, Rand E", "after": 28}, {"id": 259, "row": 13, "rs": true, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 260, "row": 14, "rs": false, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 261, "row": 15, "rs": true, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 262, "row": 16, "rs": false, "text": "Rand A, 24 li, Rand E", "after": 28}], "ends": null, "bow": null, "bindoff": null, "riddle": {"title": "Die Strichliste", "typ": "F", "hint": "Vier Folgen zu je 4 Reihen sind wie viele Striche?", "sol": "Nein. Als Nächstes kommt Reihe 16, die Rückreihe mit linken Maschen: Rand A, 24 li, Rand E.", "trap": "Vier Folgen sind 16 Reihen. Die letzte Reihe jeder Folge ist die linke Rückreihe, und genau die fehlt."}}, {"nr": 18, "kniff": "Einen Rettungsfaden einziehen", "min": "40 bis 50 Min.", "intro": "Ein dünner Hilfsfaden sichert eine korrekt gestrickte Reihe. Geht morgen beim Schachbrett etwas schief, kannst du bis hierher zurück.", "blick": "Eine richtige Reihe festhalten", "steps": [["Die Maschen zugänglich machen", "Stricke zuerst den Perlmuster-Abschnitt. Schiebe dann alle Maschen locker auf den Nadelschaft."], ["Den Hilfsfaden einziehen", "Fädle etwa 80 cm dünnen, glatten Hilfsfaden in die Wollnadel. Führe sie wie zum Linksstricken durch jede Masche, neben der Stricknadel. Die Maschen bleiben auf der Nadel."], ["Alle Schlingen prüfen", "Der Faden muss durch alle 28 Maschen laufen. Die Ringe lässt du aus."], ["Die Enden sichern", "Verknote die Enden locker, mit genug Spiel für die Breite. Morgen strickst du einfach darüber weiter."]], "photos": [{"src": "assets/fotos/t20-entdecken.webp", "cap": "Ein Rettungsfaden sichert eine Reihe", "slot": "entdecken"}, {"src": "assets/fotos/t20-schritt-1.webp", "cap": "Die Maschen auf der Nadel zugänglich machen", "slot": "schritt-1"}, {"src": "assets/fotos/t20-schritt-2.webp", "cap": "Den Hilfsfaden neben der Nadel einziehen", "slot": "schritt-2"}, {"src": "assets/fotos/t20-detail-1.webp", "cap": "Jede Masche muss gesichert sein", "slot": "detail-1"}, {"src": "assets/fotos/t20-detail-2.webp", "cap": "Über dem Rettungsfaden weiterstricken", "slot": "detail-2"}, {"src": "assets/fotos/t20-ergebnis.webp", "cap": "Der Rettungsfaden bleibt in seiner Reihe", "slot": "ergebnis"}], "hakt": [["Der Hilfsfaden steigt mit auf.", "Du hast ihn mitgestrickt oder durchstochen. Trenne die beiden Fäden beim Weiterstricken deutlich."], ["Eine Schlinge wurde übersprungen.", "Ziehe den Hilfsfaden bis vor die Lücke zurück und fädle ihn erneut durch die fehlende und alle folgenden Maschen."]], "ww": "Ein Rettungsfaden ist ein Lesezeichen, das dich vor dir selbst schützt.", "block": "Perlmuster", "sIntro": "Perlmuster, das du schon kennst. Am Ende kommt der Rettungsfaden hinein.", "sVor": "", "sCheck": "28 Maschen und 2 Ringe. Der Rettungsfaden läuft durch alle 28.", "sAfter": "Der Rettungsfaden sichert den Stand. Einen vorhandenen Fehler repariert er nicht, deshalb heute vorher zählen.", "lines": [["Alle Hinreihen", "Rand A, 12-mal [1 re, 1 li], Rand E"], ["Alle Rückreihen", "Rand A, 12-mal [1 li, 1 re], Rand E"]], "end": 28, "rows": [{"id": 263, "row": 1, "rs": true, "text": "Rand A, 12-mal [1 re, 1 li], Rand E", "after": 28}, {"id": 264, "row": 2, "rs": false, "text": "Rand A, 12-mal [1 li, 1 re], Rand E", "after": 28}, {"id": 265, "row": 3, "rs": true, "text": "Rand A, 12-mal [1 re, 1 li], Rand E", "after": 28}, {"id": 266, "row": 4, "rs": false, "text": "Rand A, 12-mal [1 li, 1 re], Rand E", "after": 28}, {"id": 267, "row": 5, "rs": true, "text": "Rand A, 12-mal [1 re, 1 li], Rand E", "after": 28}, {"id": 268, "row": 6, "rs": false, "text": "Rand A, 12-mal [1 li, 1 re], Rand E", "after": 28}, {"id": 269, "row": 7, "rs": true, "text": "Rand A, 12-mal [1 re, 1 li], Rand E", "after": 28}, {"id": 270, "row": 8, "rs": false, "text": "Rand A, 12-mal [1 li, 1 re], Rand E", "after": 28}, {"id": 271, "row": 9, "rs": true, "text": "Rand A, 12-mal [1 re, 1 li], Rand E", "after": 28}, {"id": 272, "row": 10, "rs": false, "text": "Rand A, 12-mal [1 li, 1 re], Rand E", "after": 28}, {"id": 273, "row": 11, "rs": true, "text": "Rand A, 12-mal [1 re, 1 li], Rand E", "after": 28}, {"id": 274, "row": 12, "rs": false, "text": "Rand A, 12-mal [1 li, 1 re], Rand E", "after": 28}, {"id": 275, "row": 13, "rs": true, "text": "Rand A, 12-mal [1 re, 1 li], Rand E", "after": 28}, {"id": 276, "row": 14, "rs": false, "text": "Rand A, 12-mal [1 li, 1 re], Rand E", "after": 28}, {"id": 277, "row": 15, "rs": true, "text": "Rand A, 12-mal [1 re, 1 li], Rand E", "after": 28}, {"id": 278, "row": 16, "rs": false, "text": "Rand A, 12-mal [1 li, 1 re], Rand E", "after": 28}], "ends": null, "bow": null, "bindoff": null, "riddle": {"title": "Reicht die Wolle?", "typ": "R", "hint": "Teile 224 g durch 16.", "sol": "6 g. Pro Türchen braucht Henrik 14 g, für 5 Türchen also 70 g. 300 g minus 224 g minus 70 g ergibt 6 g.", "trap": "Die 76 g, die nach Türchen 16 übrig sind, sind nicht das Ergebnis. Die letzten 5 Türchen kommen noch dazu."}}, {"nr": 19, "kniff": "Ein Schachbrettmuster stricken", "min": "40 bis 50 Min.", "intro": "Heute wachsen rechte und linke Maschen zu kleinen Feldern. Jedes Feld ist 4 Maschen breit und 4 Reihen hoch. Das schwierigste Muster deines Schals, und der Rettungsfaden liegt schon darunter.", "blick": "Nach vier Reihen die Felder tauschen", "steps": [["Vier rechts, vier links", "Stricke in Reihe 1 nach Rand A dreimal: 4 re, 4 li. Dann Rand E."], ["Drei Reihen genauso", "Reihe 2 bis 4 strickst du mit derselben Anleitung. Durch das Wenden liegen gleiche Maschenarten übereinander."], ["In Reihe 5 tauschen", "Beginne nach Rand A mit 4 li: dreimal 4 li, 4 re. Bis einschließlich Reihe 8."], ["Wiederholen", "Reihe 9 bis 16 wie Reihe 1 bis 8. Ein Strich auf dem Zettel nach jeder Reihe hilft beim Wechsel."]], "photos": [], "hakt": [["Die Felder werden lange Streifen.", "Der Wechsel nach vier Reihen fehlt. Markiere die Reihen 4, 8 und 12 auf deinem Zettel als Wechselpunkte."], ["Die Felder sind unterschiedlich breit.", "Zähle in Vierergruppen. Ein zu früher Wechsel verschiebt die Grenze um eine Masche."]], "ww": "Schachbrett: das einzige Spiel, bei dem du gegen deine eigene Strichliste antrittst.", "block": "Schachbrett", "sIntro": "Schachbrett: Felder aus 4 × 4 Maschen. Geht etwas schief, ziehst du bis zum Rettungsfaden auf und fängst den Abschnitt neu an.", "sVor": "", "sCheck": "28 Maschen und 2 Ringe. Vorn zählst du 4 Reihen Felder übereinander.", "sAfter": "Geschafft? Dann darf der Rettungsfaden morgen raus.", "lines": [["Reihe 1 bis 4 und 9 bis 12", "Rand A, 3-mal [4 re, 4 li], Rand E"], ["Reihe 5 bis 8 und 13 bis 16", "Rand A, 3-mal [4 li, 4 re], Rand E"]], "end": 28, "rows": [{"id": 279, "row": 1, "rs": true, "text": "Rand A, 3-mal [4 re, 4 li], Rand E", "after": 28}, {"id": 280, "row": 2, "rs": false, "text": "Rand A, 3-mal [4 re, 4 li], Rand E", "after": 28}, {"id": 281, "row": 3, "rs": true, "text": "Rand A, 3-mal [4 re, 4 li], Rand E", "after": 28}, {"id": 282, "row": 4, "rs": false, "text": "Rand A, 3-mal [4 re, 4 li], Rand E", "after": 28}, {"id": 283, "row": 5, "rs": true, "text": "Rand A, 3-mal [4 li, 4 re], Rand E", "after": 28}, {"id": 284, "row": 6, "rs": false, "text": "Rand A, 3-mal [4 li, 4 re], Rand E", "after": 28}, {"id": 285, "row": 7, "rs": true, "text": "Rand A, 3-mal [4 li, 4 re], Rand E", "after": 28}, {"id": 286, "row": 8, "rs": false, "text": "Rand A, 3-mal [4 li, 4 re], Rand E", "after": 28}, {"id": 287, "row": 9, "rs": true, "text": "Rand A, 3-mal [4 re, 4 li], Rand E", "after": 28}, {"id": 288, "row": 10, "rs": false, "text": "Rand A, 3-mal [4 re, 4 li], Rand E", "after": 28}, {"id": 289, "row": 11, "rs": true, "text": "Rand A, 3-mal [4 re, 4 li], Rand E", "after": 28}, {"id": 290, "row": 12, "rs": false, "text": "Rand A, 3-mal [4 re, 4 li], Rand E", "after": 28}, {"id": 291, "row": 13, "rs": true, "text": "Rand A, 3-mal [4 li, 4 re], Rand E", "after": 28}, {"id": 292, "row": 14, "rs": false, "text": "Rand A, 3-mal [4 li, 4 re], Rand E", "after": 28}, {"id": 293, "row": 15, "rs": true, "text": "Rand A, 3-mal [4 li, 4 re], Rand E", "after": 28}, {"id": 294, "row": 16, "rs": false, "text": "Rand A, 3-mal [4 li, 4 re], Rand E", "after": 28}], "ends": null, "bow": null, "bindoff": null, "riddle": {"title": "Buchstabensalat", "typ": "B", "hint": "Ein Wort ist das, was du gerade strickst. Ein anderes ist die ganze Zeit vor Weihnachten.", "sol": "SCHAL, MUSTER, FELD, ADVENT.", "trap": "CHLAS lässt sich auch zu „lasch“ legen. Gesucht ist aber ein Hauptwort."}}, {"nr": 20, "kniff": "Eine schmale Blende stricken", "min": "35 bis 45 Min.", "intro": "Die zwei Randmaschen sind seit Türchen 2 dabei. Heute schaust du dir an, warum dein Schal deshalb flach liegt und nicht einrollt.", "blick": "Zwei Randmaschen auf jeder Seite", "steps": [["Die Hinreihe", "In der Hinreihe strickst du zwischen den Rändern alle Maschen rechts. Rand A und Rand E bleiben wie immer."], ["Die Rückreihe beginnen", "Nach Rand A führst du den Faden zwischen den Spitzen nach vorn."], ["Die Mitte links stricken", "Stricke 24 li. Auf der linken Nadel bleiben jetzt genau 2 Maschen."], ["Die Blende abschließen", "Faden zwischen den Spitzen nach hinten, Rand E. So bleiben an beiden Seiten Querrippen, auch über einer glatten Fläche."]], "photos": [{"src": "assets/fotos/t14-entdecken.webp", "cap": "Glatte Mitte, krause Blende", "slot": "entdecken"}, {"src": "assets/fotos/t14-schritt-1.webp", "cap": "Die Hinreihe auf der Nadel", "slot": "schritt-1"}, {"src": "assets/fotos/t14-schritt-2.webp", "cap": "Die Rückreihe beginnt am krausen Rand", "slot": "schritt-2"}, {"src": "assets/fotos/t14-detail-1.webp", "cap": "Glatte Mitte und krauser Rand", "slot": "detail-1"}, {"src": "assets/fotos/t14-detail-2.webp", "cap": "Die Randmaschen in Nahaufnahme", "slot": "detail-2"}, {"src": "assets/fotos/t14-ergebnis.webp", "cap": "Der Rand bleibt flach", "slot": "ergebnis"}], "hakt": [["Die Blende sieht glatt aus.", "Du hast die Randmaschen in der Rückreihe links gestrickt. Rand A und Rand E sind in jeder Reihe rechts."], ["Die Mitte hat eine Querrippe.", "In der Rückreihe werden alle 24 Mustermaschen links gestrickt. Ein Strich pro Reihe hilft."]], "ww": "Gönn einem Rand zwei rechte Maschen, und er rollt sich nie wieder ein. Ganz ohne Überredung.", "block": "Glatte Fläche", "sIntro": "Die letzte große glatte Fläche. Hier siehst du am besten, was die Blende leistet.", "sVor": "Ist das Schachbrett gelungen? Dann öffne den Knoten und ziehe den Rettungsfaden seitlich heraus.", "sCheck": "28 Maschen und 2 Ringe.", "sAfter": "Morgen wird abgekettet.", "lines": [["Alle Hinreihen", "Rand A, 24 re, Rand E"], ["Alle Rückreihen", "Rand A, 24 li, Rand E"]], "end": 28, "rows": [{"id": 295, "row": 1, "rs": true, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 296, "row": 2, "rs": false, "text": "Rand A, 24 li, Rand E", "after": 28}, {"id": 297, "row": 3, "rs": true, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 298, "row": 4, "rs": false, "text": "Rand A, 24 li, Rand E", "after": 28}, {"id": 299, "row": 5, "rs": true, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 300, "row": 6, "rs": false, "text": "Rand A, 24 li, Rand E", "after": 28}, {"id": 301, "row": 7, "rs": true, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 302, "row": 8, "rs": false, "text": "Rand A, 24 li, Rand E", "after": 28}, {"id": 303, "row": 9, "rs": true, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 304, "row": 10, "rs": false, "text": "Rand A, 24 li, Rand E", "after": 28}, {"id": 305, "row": 11, "rs": true, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 306, "row": 12, "rs": false, "text": "Rand A, 24 li, Rand E", "after": 28}, {"id": 307, "row": 13, "rs": true, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 308, "row": 14, "rs": false, "text": "Rand A, 24 li, Rand E", "after": 28}, {"id": 309, "row": 15, "rs": true, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 310, "row": 16, "rs": false, "text": "Rand A, 24 li, Rand E", "after": 28}], "ends": null, "bow": null, "bindoff": null, "riddle": {"title": "Nadeln und Abende", "typ": "L", "hint": "Ordne zuerst die Abende, dann die Nadeln.", "sol": "Irma strickt am Mittwoch mit 4 mm, Dagmar am Freitag mit 6 mm, Fiete am Montag mit 8 mm.", "trap": "Fiete bleibt nur der Montag. Damit strickt Irma am Mittwoch und nimmt 4 mm."}}, {"nr": 21, "kniff": "Maschen locker abketten", "min": "35 bis 45 Min.", "intro": "Beim Abketten schließt du die offenen Maschen nacheinander. Danach ist dein Schal zum ersten Mal von der Nadel.", "blick": "Eine ruhige Abschlusskante", "steps": [["Zwei Maschen rechts stricken", "Stricke die ersten beiden Maschen rechts. Halte sie locker auf dem dicken Teil der Nadel."], ["Die ältere Masche anheben", "Stich mit der linken Nadelspitze in die zuerst gestrickte der beiden Maschen. Sie liegt weiter von der Spitze entfernt."], ["Über die jüngere Masche ziehen", "Hebe die ältere Masche über die jüngere und über die Nadelspitze hinweg. Die jüngere bleibt auf der Nadel."], ["Mit der nächsten Masche fortfahren", "Stricke die nächste Masche rechts und hebe wieder die ältere über die jüngere. Wiederhole, bis links keine Masche mehr liegt."]], "photos": [{"src": "assets/fotos/t11-entdecken.webp", "cap": "Eine ruhige Abschlusskante", "slot": "entdecken"}, {"src": "assets/fotos/t11-schritt-1.webp", "cap": "Zwei Maschen auf der rechten Nadel", "slot": "schritt-1"}, {"src": "assets/fotos/t11-schritt-2.webp", "cap": "Die Nadelspitzen an der Abkettstelle", "slot": "schritt-2"}, {"src": "assets/fotos/t11-detail-1.webp", "cap": "Die jüngere Masche sicher halten", "slot": "detail-1"}, {"src": "assets/fotos/t11-detail-2.webp", "cap": "Die Schlingen locker auf dem Schaft", "slot": "detail-2"}, {"src": "assets/fotos/t11-ergebnis.webp", "cap": "Die Abkettkante: eine kleine Kette", "slot": "ergebnis"}], "hakt": [["Die Kante zieht sich zusammen.", "Arbeite die Schlingen auf dem dicken Teil der Nadel und halte den Faden lockerer. Zur Not kettest du mit einer dickeren Nadel ab."], ["Die jüngere Masche rutscht mit.", "Halte sie mit der rechten Nadel fest, während du nur die ältere überhebst."]], "ww": "Abketten ist der Moment, in dem dein Schal zum ersten Mal ohne dich auskommt.", "block": "Kraus-Saum", "sIntro": "Der Saum oben, passend zum Anfang aus Türchen 1. Danach kettest du ab.", "sVor": "Die Ringe nimmst du beim Abketten ab, wenn du sie erreichst.", "sCheck": "Nach Reihe 14: 28 Maschen. Nach dem Abketten: keine Masche mehr auf der Nadel.", "sAfter": "Dein Schal ist von der Nadel. Lass das Fadenende hängen, morgen wird vernäht.", "lines": [["Reihe 1 bis 14", "Rand A, 24 re, Rand E"]], "end": 28, "rows": [{"id": 311, "row": 1, "rs": true, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 312, "row": 2, "rs": false, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 313, "row": 3, "rs": true, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 314, "row": 4, "rs": false, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 315, "row": 5, "rs": true, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 316, "row": 6, "rs": false, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 317, "row": 7, "rs": true, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 318, "row": 8, "rs": false, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 319, "row": 9, "rs": true, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 320, "row": 10, "rs": false, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 321, "row": 11, "rs": true, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 322, "row": 12, "rs": false, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 323, "row": 13, "rs": true, "text": "Rand A, 24 re, Rand E", "after": 28}, {"id": 324, "row": 14, "rs": false, "text": "Rand A, 24 re, Rand E", "after": 28}], "ends": null, "bow": null, "bindoff": "Kette alle 28 Maschen locker rechts ab. Wenn nur noch eine Schlinge auf der Nadel liegt, schneidest du den Faden mit 15 cm Rest ab und ziehst ihn durch diese letzte Schlinge.", "riddle": {"title": "Wortsuche", "typ": "W", "hint": "Fang mit dem längsten Wort an: PLÄTZCHEN beginnt in Zeile 3.", "sol": "Die Lage aller acht Wörter siehst du im Lösungsgitter.", "trap": ""}}, {"nr": 22, "kniff": "Ein Fadenende vernähen", "min": "20 bis 30 Min.", "intro": "Heute verschwinden die Fäden. Sechs Enden hängen an deinem Schal, und alle bekommen einen sauberen Abschluss.", "blick": "Den Faden im Gestrick sichern", "steps": [["Das Ende einfädeln", "Fädle das Fadenende in die stumpfe Wollnadel. Lege den Schal mit der Rückseite nach oben."], ["Durch mehrere Bögen führen", "Führe die Wollnadel nahe am Rand unter die rückseitigen Maschenbögen. Folge ihrem Verlauf seitwärts, statt gerade durch die Fläche zu stechen."], ["Die Richtung wechseln", "Führe den Faden einige Zentimeter versetzt zurück. Er soll in der Maschenstruktur verlaufen."], ["Glattstreichen und kontrollieren", "Ziehe das Stück sanft in Breite und Länge. Erst wenn alles flach liegt, schneidest du den Rest ab."]], "photos": [{"src": "assets/fotos/t12-entdecken.webp", "cap": "Das Fadenende verschwindet im Gestrick", "slot": "entdecken"}, {"src": "assets/fotos/t12-schritt-1.webp", "cap": "Das Fadenende einfädeln", "slot": "schritt-1"}, {"src": "assets/fotos/t12-schritt-2.webp", "cap": "Die Wollnadel unter die Bögen führen", "slot": "schritt-2"}, {"src": "assets/fotos/t12-detail-1.webp", "cap": "Der Fadenweg unter den Maschenbögen", "slot": "detail-1"}, {"src": "assets/fotos/t12-detail-2.webp", "cap": "Flachlegen und die Spannung prüfen", "slot": "detail-2"}, {"src": "assets/fotos/t12-ergebnis.webp", "cap": "Kein Faden mehr zu sehen", "slot": "ergebnis"}], "hakt": [["Die Fläche kräuselt sich.", "Du hast den Faden zu straff nachgezogen. Lockere den Weg vorsichtig mit der Wollnadel."], ["Das Ende rutscht heraus.", "Führe es durch weitere Bögen und wechsle noch einmal versetzt die Richtung."]], "ww": "Ein Strickstück ist erst fertig, wenn kein Faden mehr heraushängt. Sagt die Fadenpolizei.", "block": "Fäden vernähen", "sIntro": "Sechs Enden, sechs Häkchen. Vernähe jedes Ende in einem Abschnitt seiner eigenen Farbe, dann ist es unsichtbar.", "sVor": null, "sCheck": "6 Enden vernäht, kein Faden mehr zu sehen.", "sAfter": "Ein Hilfsfaden, der noch irgendwo steckt? Jetzt herausziehen.", "lines": [], "end": null, "rows": [], "ends": ["Anschlag, Türchen 1 (Farbe A)", "Ende Farbe A, Türchen 15", "Anfang Farbe B, Türchen 15", "Ende Farbe B, Türchen 16", "Neuer Anfang Farbe A, Türchen 16", "Abkettkante, Türchen 21 (Farbe A)"], "bow": null, "bindoff": null, "riddle": {"title": "Unsichtbar", "typ": "R", "hint": "Wie viel bleibt von jedem Ende übrig, nachdem 3 cm abgeschnitten sind?", "sol": "72 cm: Von jedem Ende bleiben 12 cm im Gestrick, 6-mal.", "trap": "18 cm ist die Menge, die abgeschnitten wird. Gefragt ist der Teil, der im Schal bleibt."}}, {"nr": 23, "kniff": "Das Gestrick in Form legen", "min": "20 Min. und Trockenzeit", "intro": "Die letzte Form entsteht oft erst nach der Pflege. Lauwarmes Wasser entspannt die Maschen, und die Abschnitte gleichen sich an.", "blick": "Wasser ausdrücken und flach trocknen", "steps": [["Behutsam waschen", "Wasche oder benetze den Schal so, wie es die Banderole erlaubt. Bewege ihn vorsichtig. Reibe und knete ihn nicht."], ["Das Wasser herausdrücken", "Hebe den Schal mit beiden Händen gestützt heraus. Drücke das Wasser sanft aus, ohne zu wringen."], ["Im Handtuch ausdrücken", "Lege ihn flach auf ein Handtuch, rolle beides locker auf und drücke auf die Rolle."], ["Flach trocknen lassen", "Lege den Schal auf eine trockene Unterlage. Richte Kanten und Abschnitte mit den Fingern aus, ohne kräftig zu dehnen."]], "photos": [{"src": "assets/fotos/t23-entdecken.webp", "cap": "Wasser, Handtuch, eine ebene Fläche", "slot": "entdecken"}, {"src": "assets/fotos/t23-schritt-1.webp", "cap": "Behutsam waschen", "slot": "schritt-1"}, {"src": "assets/fotos/t23-schritt-2.webp", "cap": "Wasser vorsichtig ausdrücken", "slot": "schritt-2"}, {"src": "assets/fotos/t23-detail-1.webp", "cap": "Restwasser im Handtuch aufnehmen", "slot": "detail-1"}, {"src": "assets/fotos/t23-detail-2.webp", "cap": "Flach in Form trocknen lassen", "slot": "detail-2"}, {"src": "assets/fotos/t23-ergebnis.webp", "cap": "Glatt und in Form", "slot": "ergebnis"}], "hakt": [["Der Schal wird beim Anheben länger.", "Nasses Gestrick ist schwer. Stütze ihn mit beiden Händen und lege ihn vorsichtig flach."], ["Er ist innen noch feucht.", "Warte mit dem Verpacken. Starke Hitze ersetzt keine Trockenzeit."]], "ww": "Wolle mag lauwarmes Wasser, sanfte Hände und keine Eile. Da ist sie nicht allein.", "block": "Waschen und spannen", "sIntro": "Ein Schal aus dickem Garn braucht oft ein bis zwei Tage zum Trocknen. Wenn er morgen Abend noch feucht ist, verschenkst du ihn eben am ersten Feiertag.", "sVor": null, "sCheck": "Länge und Breite vorher und nachher notiert.", "sAfter": "Kein Platz oder keine Zeit? Dann lass das Waschen aus. Dein Schal ist auch so fertig, nur etwas unruhiger.", "lines": [], "end": null, "rows": [], "ends": null, "bow": null, "bindoff": null, "riddle": {"title": "Finde den Fehler", "typ": "F", "hint": "Denk an Türchen 11 und 12: Was verändert die Maschenzahl, was nicht?", "sol": "D.", "trap": "Ein Ring wird nur weitergereicht und zählt nie als Masche. Wer 30 statt 28 zählt, hat die Ringe mitgezählt."}}, {"nr": 24, "kniff": "Eine kleine Strickschleife formen", "min": "30 bis 40 Min.", "intro": "Zum letzten Türchen wird aus einem kleinen Rechteck eine Schleife für dein Geschenk. Die Mitte entsteht durch Falten und Umwickeln.", "blick": "Das Rechteck bekommt eine Mitte", "steps": [["Die Mitte finden", "Lege das Rechteck mit der langen Kante waagerecht vor dich. Falte es einmal von links nach rechts, um die Mitte zu finden, und öffne es wieder."], ["Die Mitte zusammendrücken", "Raffe die Mitte von oben nach unten zu zwei oder drei kleinen Falten. Halte sie zwischen Daumen und Zeigefinger."], ["Die Mitte umwickeln", "Lege etwa 50 cm Garn um die geraffte Mitte. Lass 15 cm Anfang frei und wickle drei- bis fünfmal darum."], ["Hinten befestigen", "Verknote Anfang und Ende auf der Rückseite doppelt und führe beide Enden unter der Wicklung hindurch. Kürze erst dann."]], "photos": [{"src": "assets/fotos/t24-entdecken.webp", "cap": "Ein Geschenk mit Strickschleife", "slot": "entdecken"}, {"src": "assets/fotos/t24-schritt-1.webp", "cap": "Das kleine Rechteck", "slot": "schritt-1"}, {"src": "assets/fotos/t24-schritt-2.webp", "cap": "Die Mitte zusammendrücken", "slot": "schritt-2"}, {"src": "assets/fotos/t24-detail-1.webp", "cap": "Die Mitte mit Garn umwickeln", "slot": "detail-1"}, {"src": "assets/fotos/t24-detail-2.webp", "cap": "Die Wicklung auf der Rückseite sichern", "slot": "detail-2"}, {"src": "assets/fotos/t24-ergebnis.webp", "cap": "Die fertige Schleife", "slot": "ergebnis"}], "hakt": [["Eine Seite ist größer.", "Löse die Wicklung und verschiebe sie zur tatsächlichen Mitte."], ["Die Mitte wird sehr dick.", "Forme weniger Falten und wickle nur so oft wie nötig."]], "ww": "Jetzt hat der Schal eine Schleife. Und du einen guten Grund, im Januar den nächsten anzuschlagen.", "block": "Schleife und Geschenk", "sIntro": "Das Rechteck strickst du aus dem Rest von Farbe B. Alles, was du dafür brauchst, kannst du inzwischen.", "sVor": null, "sCheck": "Eine Schleife, ein Schal, 24 Türchen.", "sAfter": "", "lines": [], "end": null, "rows": [], "ends": null, "bow": ["Schlage mit Farbe B 14 Maschen an.", "Stricke 14 Reihen kraus rechts, also alle Maschen rechts.", "Kette locker ab und vernähe beide Enden.", "Das Rechteck misst ungefähr 10 × 5 cm. Forme die Schleife wie auf der Kniff-Seite."], "bindoff": null, "riddle": {"title": "Wer bekommt welchen Schal?", "typ": "L", "hint": "Beginne mit dem Hinweis, der einen Schal einer Person sicher zuordnet.", "sol": "Hedda schenkt der Nachbarin einen grünen Schal, Theo der Oma einen roten, Leni dem Bruder einen weißen.", "trap": "Theo bleibt nur Rot, und Rot geht an die Oma."}}], "help": [{"id": "zuviel", "s": "Eine Masche zu viel", "a": "Meist ein ungewollter Umschlag: Der Faden lag über der Nadel statt zwischen den Spitzen. Geh die letzte Reihe Masche für Masche durch. Ein Umschlag sieht aus wie eine schräge Schlinge ohne Masche darunter. Lass ihn von der Nadel gleiten.", "doors": [4, 12]}, {"id": "zuwenig", "s": "Eine Masche fehlt", "a": "Zähle alle Schlingen auf der Nadel. Fehlt eine, ist sie wahrscheinlich heruntergerutscht. Such im Gestrick nach einer kleinen Leiter oder einer offenen Schlinge und sichere sie sofort.", "doors": [6, 13]}, {"id": "gefallen", "s": "Eine Masche ist heruntergefallen", "a": "Sichere sie mit dem verschließbaren Markierer, damit sie nicht weiterläuft. Dann holst du sie mit der Häkelnadel Querfaden für Querfaden wieder hoch.", "doors": [13, 14]}, {"id": "muster", "s": "Das Muster stimmt nicht", "a": "Schau, wie die Maschen erscheinen: Rechte Maschen sind kleine V, linke Maschen kleine Bögen. Vergleiche das mit der Strickschrift im Buch.", "doors": [5]}, {"id": "reihe", "s": "Ich weiß nicht, welche Reihe dran ist", "a": "Die App merkt sich deinen Stand. Hast du ohne App weitergestrickt, zähle die Reihen im Gestrick ab dem Beginn des Türchens und stell die Reihe in der App ein.", "doors": [7]}, {"id": "rand", "s": "Der Rand zieht sich zusammen", "a": "Zieh die Masche nach dem Abheben nicht fest. Der Randfaden muss zwei Reihen überbrücken können.", "doors": [3]}, {"id": "loch", "s": "Da ist ein Loch", "a": "Ein Loch neben dem Rand entsteht oft beim Wechsel nach hinten: Der Faden lief über die Nadel und hat einen Umschlag gebildet. Im Lochmuster von Türchen 12 gehören die Löcher dazu.", "doors": [3, 12]}, {"id": "auftrennen", "s": "Ich muss ein Stück auftrennen", "a": "Zieh bis zum Rettungsfaden zurück und nimm die Maschen von dort wieder auf. Danach zählst du einmal nach: 28 Maschen.", "doors": [18]}, {"id": "wolle", "s": "Die Wolle wird knapp", "a": "Stricke in Türchen 20 nur 8 statt 16 Reihen. Der Schal wird dann ein paar Zentimeter kürzer.", "doors": [17]}, {"id": "faden", "s": "Ein Fadenende löst sich", "a": "Führe es durch weitere Bögen und wechsle die Richtung versetzt. Erst dann abschneiden.", "doors": [22]}]};
